    /* ===================================================================================== *
     *  INVARIANT 243 - THE PERSONAL SCALE (0.10, the owner's decisions). The arithmetic is    *
     *  core's and JUnit pins it (ScaleTest, ScaleSweepTest, RoutineOffsetTest,              *
     *  QuickAdjustTest); this pins that the app keeps asking it:                            *
     *   - the plan's figure is what a save or a rewrite writes back (TrainerTab.savedPlanKpa)*
     *     and a track's prescription comes through TrainerTab.trackRx - never the scaled   *
     *     figure written as the plan's, which would add the offset at every save;           *
     *   - a session carries its routine's scale, so the Level 1 gate reads the plan's figure;*
     *   - the counting line the run screen draws is the one the session is scored against *
     *     (Model.scaledLevelFloorKpa);                                                     *
     *   - the run screen's programme caps are asked once, never skipped: the strip asks     *
     *     a.pullWarningNow(, the routine offset a.routineOffsetWarning(, and the offset is   *
     *     held per step to the run's hard limits (runHardLimits());                          *
     *   - the Trainer's My pressure asks Scale.needsWarning( and never writes the plan's    *
     *     figure; Adjust first steps through RxBuild.adjustBumpKpa( (the engine's month, a  *
     *     "+" that never lowers); setup keeps the answer as the offset and asks first;      *
     *   - every build ends on RxBuild's holdToHardLimits( and stamps its scale, the traction *
     *     pull at Scale.pullCapKpa(; the signature carries the offset (Scale.offsetTag().  *
     * ===================================================================================== */

    /** {file, "m" method (longest overload) or "c" class, name, required (each of the
     *  '|'-separated snippets, whitespace ignored), forbidden (any), why}. */
    static final String[][] SCALE_RULES = {
        { "SessionActivity.java", "m", "evalTrack", "TrainerTab.trackRx(", "",
          "prescribes outside the personal scale's door" },
        { "SessionActivity.java", "m", "saveMint", "TrainerTab.savedPlanKpa(",
          "setWorkingPressure(use.pressureKpa", "writes the scaled figure back as the plan's" },
        { "SessionActivity.java", "m", "applyPlanTo", "TrainerTab.savedPlanKpa(",
          "setWorkingPressure(built.pressureKpa", "writes the scaled figure back as the plan's" },
        { "SessionActivity.java", "m", "lighterDayNet", "TrainerTab.savedPlanKpa(",
          "setWorkingPressure(todayRx.pressureKpa", "writes the scaled figure back as the plan's" },
        { "SessionActivity.java", "m", "fileSession", "rec.scaleKpa=r.trainerScaleKpa", "",
          "files a session without its routine's scale - the gate would read the scaled pull" },
        { "SessionActivity.java", "m", "applyRoutineOffset", "runHardLimits()", "",
          "offsets a run without each step's hard limit" },
        { "SessionActivity.java", "m", "tupCountFloorNowKpa", "Model.scaledLevelFloorKpa(",
          "tupCountFloorKpa(Plan.floorKpa(", "draws a counting line the session is not scored on" },
        { "RunScreen.java", "m", "stripStep", "a.pullWarningNow(", "",
          "never asks before the strip's pull passes its usual limit" },
        { "RunScreen.java", "c", "RoutineOffsetStep", "a.routineOffsetWarning(", "",
          "never asks before the offset passes its usual cap" },
        { "RunScreen.java", "m", "sheetPullCap", "a.stripPullCapKpa()",
          "QuickAdjust.pullCeiling(", "dials the pull past what the strip allows" },
        { "RunScreen.java", "m", "paintNetRow", "Model.scaledLevelFloorKpa(", "",
          "prints a counting line the session is not scored on" },
        { "TrainerScreen.java", "c", "BumpTrackOffset", "Scale.needsWarning(|setTrackOffset(",
          "setWorkingPressure(", "moves the plan's figure, or the offset unasked" },
        { "TrainerScreen.java", "c", "BumpMintKpa", "RxBuild.adjustBumpKpa(",
          "TrainerTab.monthsBetween(|Mint.clampPressureKpa(",
          "steps Adjust first past its limits or at the wrong month" },
        { "TrainerScreen.java", "c", "CommitOnboardTap",
          "askBeforeCommit()|onboardGirthSplit()|.offsetKpa=", "",
          "clamps the setup's answer instead of keeping it as the offset, or keeps it unasked" },
        { "RxBuild.java", "m", "build", "holdToHardLimits(|.trainerScaleKpa=", "",
          "builds without the hard limits or its scale" },
        { "RxBuild.java", "m", "tractionRoutineFromRx",
          "holdToHardLimits(|.trainerScaleKpa=|Scale.pullCapKpa(", "",
          "builds a traction session without the hard limits, its scale or the pull's cap" },
        { "Model.java", "m", "scoringFloorKpa", "scaledLevelFloorKpa(", "",
          "scores a session against a line that ignores its scale" },
        { "Model.java", "m", "mintShapeTag", "Scale.offsetTag(", "",
          "signs a prescription without its offset - a new offset would never reach a routine" },
    };

    static String scaleSite(String[] rule) { return rule[0] + "#" + rule[2]; }

