    /** Prepends a stillUnsafe() declaration: the chooser check is scoped to the file that
     *  owns the safety question, and these snippets stand in for that file. */
    /* ===================================================================================== *
     *  INVARIANTS 220-223 - ROBUST 0.10: THE STORED DATA'S OWN GUARANTEES (2026-09-27).     *
     *  The rules are pure and JUnit pins them (AtomicFileTest, UnknownKeysTest,             *
     *  StrayPhotosTest, StdMomentTest); these pin that the code keeps asking them. Each     *
     *  reads its files BY NAME from the flat source folder - a file that is missing is a    *
     *  violation, never a silent pass.                                                      *
     * ===================================================================================== */

    /** One file of the flat source folder, comments stripped and literals blanked; null
     *  (and a violation) when it is not there. */
    static String robustSource(String dir, String name, List<String> violations)
            throws IOException {
        File f = new File(dir, name);
        if (!f.isFile()) {
            violations.add("invariants 220-223 read " + name + " but it is not under " + dir
                + " - renamed or moved? Update the check deliberately rather than let a "
                + "rename disable it");
            return null;
        }
        return blankStringLiterals(stripComments(
            new String(Files.readAllBytes(f.toPath()), "UTF-8")));
    }

    static void checkRobust010(String dir, List<String> violations) throws IOException {
        String store = robustSource(dir, "Store.java", violations);
        String atomic = robustSource(dir, "AtomicFile.java", violations);
        if (store != null && atomic != null) checkDurableSave(store, atomic, violations);
        String model = robustSource(dir, "Model.java", violations);
        if (model != null) checkUnknownKeysKept(model, violations);
        String activity = robustSource(dir, "SessionActivity.java", violations);
        if (activity != null) {
            // Every OTHER Android source, for 222's "one place" half.
            List<String> others = new ArrayList<String>();
            List<String> everyAndroid = new ArrayList<String>();
            List<String> android = androidSources(dir);
            for (int i = 0; i < android.size(); i++) {
                String src = blankStringLiterals(stripComments(new String(
                    Files.readAllBytes(Paths.get(android.get(i))), "UTF-8")));
                everyAndroid.add(src);
                if (new File(android.get(i)).getName().equals("SessionActivity.java")) continue;
                others.add(src);
            }
            checkStraySweep(activity, others, violations);
            checkStdMoment(activity, everyAndroid, violations);
        }
    }

    /**
     * INVARIANT 220 (durable save): EVERY USER-DATA FILE IS REPLACED THROUGH AtomicFile, AND
     * AtomicFile FORCES THE BYTES TO THE DISK BEFORE THE RENAME.
     *   (a) Store's save, writeAsRun and writeTau each call replaceSynced(, and replaceSynced
     *       calls AtomicFile.save( - no user-data file is written any other way;
     *   (b) Store opens no FileOutputStream and calls no openFileOutput( of its own, and
     *       renames only in quarantine (setting an unreadable file aside);
     *   (c) AtomicFile.writeSynced calls getFD().sync() before its first close();
     *       AtomicFile.replace writes through writeSynced( before its renameTo(, and never
     *       deletes the destination (no file at the real name reads as a fresh install).
     */
    static final String[] DURABLE_WRITERS = { "save", "writeAsRun", "writeTau" };

    static void checkDurableSave(String store, String atomic, List<String> violations) {
        for (int i = 0; i < DURABLE_WRITERS.length; i++) {
            int[] b = findMethodBodySpan(store, DURABLE_WRITERS[i]);
            if (b == null) {
                violations.add("Store.java: invariant 220 names " + DURABLE_WRITERS[i]
                    + " but Store has no such method - renamed? Update the check deliberately");
                continue;
            }
            if (store.substring(b[0], b[1]).indexOf("replaceSynced(") < 0)
                violations.add("Store.java: invariant 220 - " + DURABLE_WRITERS[i] + " at line "
                    + lineOf(store, b[0]) + " must write through replaceSynced( (tmp, sync, "
                    + "rename)");
        }
        int[] rs = findMethodBodySpan(store, "replaceSynced");
        if (rs == null || store.substring(rs[0], rs[1]).indexOf("AtomicFile.save(") < 0)
            violations.add("Store.java: invariant 220 - replaceSynced must call AtomicFile.save(");
        Matcher fo = Pattern.compile("\\bnew\\s+FileOutputStream\\s*\\(|\\bopenFileOutput\\s*\\(")
            .matcher(store);
        if (fo.find())
            violations.add("Store.java: invariant 220 - a write of its own at line "
                + lineOf(store, fo.start()) + " - every user-data file goes through AtomicFile");
        int[] q = findMethodBodySpan(store, "quarantine");
        Matcher rn = Pattern.compile("\\.renameTo\\s*\\(").matcher(store);
        while (rn.find())
            if (q == null || rn.start() < q[0] || rn.start() > q[1])
                violations.add("Store.java: invariant 220 - renameTo at line "
                    + lineOf(store, rn.start()) + " outside quarantine - a rename that was not "
                    + "preceded by AtomicFile's sync can publish bytes that never reached disk");
        int[] ws = findMethodBodySpan(atomic, "writeSynced");
        if (ws == null) {
            violations.add("AtomicFile.java: invariant 220 names writeSynced but it is gone");
        } else {
            String body = atomic.substring(ws[0], ws[1]).replaceAll("\\s", "");
            int sync = body.indexOf(".getFD().sync()");
            int close = body.indexOf(".close()");
            if (sync < 0 || (close >= 0 && close < sync))
                violations.add("AtomicFile.java: invariant 220 - writeSynced at line "
                    + lineOf(atomic, ws[0]) + " must call getFD().sync() before close()");
        }
        int[] rp = findMethodBodySpan(atomic, "replace");
        if (rp == null) {
            violations.add("AtomicFile.java: invariant 220 names replace but it is gone");
        } else {
            String body = atomic.substring(rp[0], rp[1]).replaceAll("\\s", "");
            int w = body.indexOf("writeSynced(");
            int r = body.indexOf("renameTo(");
            if (w < 0 || r < 0 || r < w)
                violations.add("AtomicFile.java: invariant 220 - replace at line "
                    + lineOf(atomic, rp[0]) + " must write through writeSynced( before renameTo(");
            if (body.indexOf("dst.delete(") >= 0)
                violations.add("AtomicFile.java: invariant 220 - replace at line "
                    + lineOf(atomic, rp[0]) + " deletes the destination - between that and the "
                    + "rename there is no file, and a load that finds none starts fresh");
        }
    }

    /** Invariant 220's self-tests: the app's shapes pass, each rule rejects its shape. */
    static void durableSaveSelfTests(int[] counts) {
        String store =
              "public static void save(Context c, Model m) {\n"
            + "    File dir = c.getFilesDir();\n"
            + "    replaceSynced(new File(dir, TMP), new File(dir, FILE), data);\n"
            + "}\n"
            + "private static void replaceSynced(File tmp, File dst, byte[] data) {\n"
            + "    AtomicFile.save(tmp, dst, data);\n"
            + "}\n"
            + "private static void writeAsRun(Context c) { replaceSynced(a, b, d); }\n"
            + "private static void writeTau(Context c) { replaceSynced(a, b, d); }\n"
            + "private static boolean quarantine(Context c) {\n"
            + "    if (bad.renameTo(aside)) return true;\n"
            + "    return false;\n"
            + "}\n";
        String atomic =
              "public static int replace(File tmp, File dst, byte[] data) {\n"
            + "    if (!writeSynced(tmp, data)) { tmp.delete(); return WRITE_REFUSED; }\n"
            + "    if (tmp.renameTo(dst)) return REPLACED;\n"
            + "    return RENAME_REFUSED;\n"
            + "}\n"
            + "public static boolean writeSynced(File f, byte[] data) {\n"
            + "    o = new FileOutputStream(f);\n"
            + "    o.write(data);\n"
            + "    o.flush();\n"
            + "    o.getFD().sync();\n"
            + "    o.close();\n"
            + "    return true;\n"
            + "}\n";
        List<String> v = new ArrayList<String>();
        checkDurableSave(store, atomic, v);
        selfCheck(counts, v.isEmpty(), "INV220: the app's shapes pass (got " + v + ")");
        String[][] bad = {
            { "S", "a save that writes model.json itself",
              "    replaceSynced(new File(dir, TMP), new File(dir, FILE), data);\n",
              "    FileOutputStream o = new FileOutputStream(tmp); o.write(data); o.close();\n" },
            { "S", "a rename outside quarantine",
              "private static void writeTau(Context c) { replaceSynced(a, b, d); }\n",
              "private static void writeTau(Context c) { replaceSynced(a, b, d); t.renameTo(x); }\n" },
            { "S", "replaceSynced that renames without AtomicFile",
              "    AtomicFile.save(tmp, dst, data);\n", "    tmp.renameTo(dst);\n" },
            { "A", "a write that is never synced", "    o.getFD().sync();\n", "" },
            { "A", "a sync after the close",
              "    o.getFD().sync();\n    o.close();\n", "    o.close();\n    o.getFD().sync();\n" },
            { "A", "a rename before the synced write",
              "    if (!writeSynced(tmp, data)) { tmp.delete(); return WRITE_REFUSED; }\n"
              + "    if (tmp.renameTo(dst)) return REPLACED;\n",
              "    if (tmp.renameTo(dst)) return REPLACED;\n"
              + "    if (!writeSynced(tmp, data)) { tmp.delete(); return WRITE_REFUSED; }\n" },
            { "A", "delete the old file, then rename",
              "    if (tmp.renameTo(dst)) return REPLACED;\n",
              "    dst.delete();\n    if (tmp.renameTo(dst)) return REPLACED;\n" },
        };
        for (int i = 0; i < bad.length; i++) {
            boolean s = "S".equals(bad[i][0]);
            String st = s ? store.replace(bad[i][2], bad[i][3]) : store;
            String at = s ? atomic : atomic.replace(bad[i][2], bad[i][3]);
            selfCheck(counts, !(s ? st : at).equals(s ? store : atomic),
                "INV220 self-test edit did not apply: " + bad[i][1]);
            List<String> bv = new ArrayList<String>();
            checkDurableSave(st, at, bv);
            selfCheck(counts, !bv.isEmpty(), "INV220 must reject " + bad[i][1]);
        }
    }

    /** The body of the first method whose declaration matches `signature` (a regex), as
     *  {start, end}; null when there is none. */
    static int[] robustBody(String src, String signature) {
        Matcher m = Pattern.compile(signature + "[^{;]*\\{").matcher(src);
        if (!m.find()) return null;
        int close = findMatchingBrace(src, m.end() - 1);
        return close < 0 ? null : new int[]{ m.end(), close };
    }

    /** Class `cls`'s own toJson() - not one of a class nested inside it (Reading holds
     *  Photo, whose toJson comes first). */
    static int[] ownToJson(String src, String cls) {
        int[] c = robustBody(src, "class\\s+" + cls + "\\b");
        if (c == null) return null;
        String body = src.substring(c[0], c[1]);
        List<MethodSpan> nested = findAllClassBodies(body);
        Matcher m = Pattern.compile("public\\s+JSONObject\\s+toJson\\s*\\(\\s*\\)[^{;]*\\{")
            .matcher(body);
        while (m.find()) {
            boolean inNested = false;
            for (int i = 0; i < nested.size(); i++)
                if (m.start() > nested.get(i).bodyStart && m.start() < nested.get(i).bodyEnd)
                    inNested = true;
            if (inNested) continue;
            int close = findMatchingBrace(body, m.end() - 1);
            return close < 0 ? null : new int[]{ c[0] + m.end(), c[0] + close };
        }
        return null;
    }

    /**
     * INVARIANT 221 (keep unknown fields): EVERY RECORD THE MODEL LOADS KEEPS WHAT IT DOES NOT
     * KNOW, AND EVERY RECORD IT SAVES WRITES IT BACK. For the top level, each reading and each
     * photo (Model.java):
     *   (a) the loader reads through a JsonKeep.Reader (new JsonKeep.Reader( or
     *       JsonKeep.reader() and files what was never asked for (`.unknown = o.unasked(`);
     *   (b) the writer calls JsonKeep.putBack(o, unknown);
     *   (c) Reading.copy carries `c.unknown = unknown` - the reading editor saves a copy.
     * A loader that reads a plain JSONObject again would drop a newer app's keys on the next
     * save with every test of the fields still green.
     */
    static final String[][] KEEP_SITES = {
        // { what, loader signature, writer signature }
        { "Model", "public\\s+static\\s+Model\\s+fromJson\\s*\\(\\s*String",
                   "public\\s+String\\s+toJson\\s*\\(\\s*\\)" },
        { "Reading", "public\\s+static\\s+Reading\\s+fromJson\\s*\\(", null },
        { "Photo", "public\\s+static\\s+Photo\\s+fromJson\\s*\\(", null },
    };

    static void checkUnknownKeysKept(String model, List<String> violations) {
        for (int i = 0; i < KEEP_SITES.length; i++) {
            String what = KEEP_SITES[i][0];
            int[] ld = robustBody(model, KEEP_SITES[i][1]);
            if (ld == null) {
                violations.add("Model.java: invariant 221 names " + what + "'s loader but it is "
                    + "gone - renamed? Update the check deliberately");
                continue;
            }
            String lb = model.substring(ld[0], ld[1]).replaceAll("\\s", "");
            if ((lb.indexOf("newJsonKeep.Reader(") < 0 && lb.indexOf("JsonKeep.reader(") < 0)
                    || lb.indexOf(".unknown=o.unasked(") < 0)
                violations.add("Model.java: invariant 221 - " + what + "'s loader at line "
                    + lineOf(model, ld[0]) + " must read through a JsonKeep.Reader and file "
                    + "`.unknown = o.unasked(` - otherwise a newer app's keys are dropped");
            // The writer: Model's is named; a record's is the toJson inside its class body.
            int[] wr;
            if (KEEP_SITES[i][2] != null) {
                wr = robustBody(model, KEEP_SITES[i][2]);
            } else {
                wr = ownToJson(model, what);
            }
            if (wr == null) {
                violations.add("Model.java: invariant 221 names " + what + "'s writer but it is "
                    + "gone - renamed? Update the check deliberately");
                continue;
            }
            if (model.substring(wr[0], wr[1]).replaceAll("\\s", "")
                    .indexOf("JsonKeep.putBack(o,unknown)") < 0)
                violations.add("Model.java: invariant 221 - " + what + "'s writer at line "
                    + lineOf(model, wr[0]) + " must call JsonKeep.putBack(o, unknown)");
        }
        int[] cp = robustBody(model, "public\\s+Reading\\s+copy\\s*\\(\\s*\\)");
        if (cp == null || model.substring(cp[0], cp[1]).replaceAll("\\s", "")
                .indexOf("c.unknown=unknown;") < 0)
            violations.add("Model.java: invariant 221 - Reading.copy must carry "
                + "`c.unknown = unknown` - the editor saves the copy, and would drop the keys");
    }

    /** Invariant 221's self-tests. */
    static void unknownKeysSelfTests(int[] counts) {
        String model =
              "public final class Model {\n"
            + "  public static final class Reading {\n"
            + "    public Reading copy() { Reading c = new Reading(); c.unknown = unknown; return c; }\n"
            + "    public static final class Photo {\n"
            + "      public JSONObject toJson() throws JSONException {\n"
            + "        JSONObject o = new JSONObject(); o.put(a, b);\n"
            + "        JsonKeep.putBack(o, unknown);\n"
            + "        return o; }\n"
            + "      public static Photo fromJson(JSONObject src) {\n"
            + "        JsonKeep.Reader o = JsonKeep.reader(src);\n"
            + "        p.unknown = o.unasked(); return p; }\n"
            + "    }\n"
            + "    public JSONObject toJson() throws JSONException {\n"
            + "      JSONObject o = new JSONObject();\n"
            + "      JsonKeep.putBack(o, unknown);\n"
            + "      return o; }\n"
            + "    public static Reading fromJson(JSONObject src) {\n"
            + "      JsonKeep.Reader o = JsonKeep.reader(src);\n"
            + "      r.unknown = o.unasked(); return r; }\n"
            + "  }\n"
            + "  public String toJson() { JSONObject o = new JSONObject();\n"
            + "    JsonKeep.putBack(o, unknown); return o.toString(); }\n"
            + "  public static Model fromJson(String s) {\n"
            + "    JsonKeep.Reader o = new JsonKeep.Reader(s);\n"
            + "    m.unknown = o.unasked(); return m; }\n"
            + "}\n";
        List<String> v = new ArrayList<String>();
        checkUnknownKeysKept(model, v);
        selfCheck(counts, v.isEmpty(), "INV221: the app's shapes pass (got " + v + ")");
        String[][] bad = {
            { "the top level parsed plain again",
              "    JsonKeep.Reader o = new JsonKeep.Reader(s);\n",
              "    JSONObject o = new JSONObject(s);\n" },
            { "a reading that files no unknown keys",
              "      r.unknown = o.unasked(); return r; }\n", "      return r; }\n" },
            { "a photo that writes none back",
              "        JsonKeep.putBack(o, unknown);\n        return o; }\n",
              "        return o; }\n" },
            { "a copy that drops them",
              "c.unknown = unknown; return c;", "return c;" },
            { "the top level that writes none back",
              "    JsonKeep.putBack(o, unknown); return o.toString(); }\n",
              "    return o.toString(); }\n" },
        };
        for (int i = 0; i < bad.length; i++) {
            String b = model.replace(bad[i][1], bad[i][2]);
            selfCheck(counts, !b.equals(model), "INV221 self-test edit did not apply: " + bad[i][0]);
            List<String> bv = new ArrayList<String>();
            checkUnknownKeysKept(b, bv);
            selfCheck(counts, !bv.isEmpty(), "INV221 must reject " + bad[i][0]);
        }
    }

    /**
     * INVARIANT 222 (stray photos): THE START-UP SWEEP RUNS ONCE, AFTER THE LOAD, AND ASKS
     * StrayPhotos WHAT IT MAY DELETE (SessionActivity.java).
     *   (a) onCreate calls sweepStrayPhotos() after Store.load( - never before the model the
     *       sweep compares against exists;
     *   (b) sweepStrayPhotos returns first when Store.storeWasUnreadable() (the seeded
     *       stand-in would make every photo look stray), decides with StrayPhotos.toDelete(
     *       on the wall clock (System.currentTimeMillis(), the clock a file's lastModified is
     *       on), and deletes only through deletePhotoFile(;
     *   (c) nothing it logs names a file (no getName(, getAbsolutePath( or gone.get( inside a
     *       log( statement) - the debug log never holds photo paths;
     *   (d) no other Android source calls StrayPhotos.toDelete( - one sweep, one place.
     * StrayPhotosTest holds the rules themselves: no reading with the id, no reference, no
     * open capture, over 24 hours old, never on an empty library.
     */
    static void checkStraySweep(String activity, List<String> androidOthers,
                                List<String> violations) {
        int[] oc = robustBody(activity, "void\\s+onCreate\\s*\\(\\s*Bundle");
        if (oc == null) {
            violations.add("SessionActivity.java: invariant 222 found no onCreate(Bundle");
        } else {
            String b = activity.substring(oc[0], oc[1]);
            int load = b.indexOf("Store.load(");
            int sweep = b.indexOf("sweepStrayPhotos(");
            if (sweep < 0 || load < 0 || sweep < load)
                violations.add("SessionActivity.java: invariant 222 - onCreate at line "
                    + lineOf(activity, oc[0]) + " must call sweepStrayPhotos() after Store.load(");
        }
        int[] sw = robustBody(activity, "void\\s+sweepStrayPhotos\\s*\\(\\s*\\)");
        if (sw == null) {
            violations.add("SessionActivity.java: invariant 222 names sweepStrayPhotos but it is "
                + "gone - renamed? Update the check deliberately");
        } else {
            String raw = activity.substring(sw[0], sw[1]);
            String b = raw.replaceAll("\\s", "");
            int guard = b.indexOf("if(Store.storeWasUnreadable())return;");
            int ask = b.indexOf("StrayPhotos.toDelete(");
            if (guard < 0 || ask < 0 || guard > ask)
                violations.add("SessionActivity.java: invariant 222 - sweepStrayPhotos at line "
                    + lineOf(activity, sw[0]) + " must return first when "
                    + "Store.storeWasUnreadable() and then ask StrayPhotos.toDelete(");
            if (b.indexOf("System.currentTimeMillis()") < 0)
                violations.add("SessionActivity.java: invariant 222 - sweepStrayPhotos must judge "
                    + "age on System.currentTimeMillis(), the clock lastModified is on");
            if (b.indexOf("deletePhotoFile(") < 0 || b.indexOf(".delete()") >= 0)
                violations.add("SessionActivity.java: invariant 222 - sweepStrayPhotos must delete "
                    + "through deletePhotoFile( and nothing else");
            String[] stmts = raw.split(";");
            for (int i = 0; i < stmts.length; i++) {
                String st = stmts[i].replaceAll("\\s", "");
                if (st.indexOf("log(") >= 0 && (st.indexOf("getName(") >= 0
                        || st.indexOf("getAbsolutePath(") >= 0 || st.indexOf("gone.get(") >= 0))
                    violations.add("SessionActivity.java: invariant 222 - sweepStrayPhotos logs a "
                        + "file name or path - the debug log never holds photo paths");
            }
        }
        for (int i = 0; i < androidOthers.size(); i++) {
            String src = androidOthers.get(i);
            if (src.indexOf("StrayPhotos.toDelete(") >= 0)
                violations.add("invariant 222 - an Android source other than SessionActivity "
                    + "calls StrayPhotos.toDelete( - the sweep has one place");
        }
    }

    /** Invariant 222's self-tests. */
    static void straySweepSelfTests(int[] counts) {
        String act =
              "@Override protected void onCreate(Bundle b) {\n"
            + "    model = Store.load(this);\n"
            + "    sweepStrayPhotos();\n"
            + "}\n"
            + "void sweepStrayPhotos() {\n"
            + "    if (Store.storeWasUnreadable()) return;\n"
            + "    List<String> gone = StrayPhotos.toDelete(files, model.measLog, open,\n"
            + "                                             System.currentTimeMillis());\n"
            + "    for (int i = 0; i < gone.size(); i++)\n"
            + "        if (deletePhotoFile(new File(dir, gone.get(i)).getAbsolutePath())) swept++;\n"
            + "    if (!gone.isEmpty()) log(\"swept \" + swept);\n"
            + "}\n";
        List<String> none = new ArrayList<String>();
        List<String> v = new ArrayList<String>();
        checkStraySweep(act, none, v);
        selfCheck(counts, v.isEmpty(), "INV222: the app's shapes pass (got " + v + ")");
        String[][] bad = {
            { "a sweep before the load",
              "    model = Store.load(this);\n    sweepStrayPhotos();\n",
              "    sweepStrayPhotos();\n    model = Store.load(this);\n" },
            { "a sweep over an unreadable store",
              "    if (Store.storeWasUnreadable()) return;\n", "" },
            { "a sweep that decides for itself",
              "StrayPhotos.toDelete(files, model.measLog, open,", "mine(files, model.measLog, open," },
            { "a sweep that deletes directly",
              "if (deletePhotoFile(new File(dir, gone.get(i)).getAbsolutePath())) swept++;",
              "if (new File(dir, gone.get(i)).delete()) swept++;" },
            { "a sweep that logs names",
              "log(\"swept \" + swept);", "log(\"swept \" + gone.get(0));" },
        };
        for (int i = 0; i < bad.length; i++) {
            String b = act.replace(bad[i][1], bad[i][2]);
            selfCheck(counts, !b.equals(act), "INV222 self-test edit did not apply: " + bad[i][0]);
            List<String> bv = new ArrayList<String>();
            checkStraySweep(b, none, bv);
            selfCheck(counts, !bv.isEmpty(), "INV222 must reject " + bad[i][0]);
        }
        List<String> bv = new ArrayList<String>();
        checkStraySweep(act, Arrays.asList("void x() { StrayPhotos.toDelete(a, b, c, d); }"), bv);
        selfCheck(counts, !bv.isEmpty(), "INV222 must reject a second sweep elsewhere");
    }

    /**
     * INVARIANT 223 (the vacuum at the standardised moment): A STANDARDISED READING'S VACUUM
     * IS THE ONE AT THE END OF THE COUNT (StdMoment).
     *   (a) SessionActivity: where the count opens the two minutes (`stdWindowEndsAt = now +
     *       STD_PHOTO_WINDOW_MS;`), the same block records `stdCountEndKpa =
     *       observedNowOrNull();` and `stdCountEndPhotoKpa = PhotoTruth.shutterKpa(` - each by
     *       its own freshness rule;
     *   (b) every method that starts a new count (`stdWindowEndsAt = 0;`) also clears both -
     *       a count-end sample never outlives its count;
     *   (c) fileObservedKpa files `StdMoment.readingKpa(stdCountEndKpa,` and
     *       `StdMoment.readingKpaAt(stdCountEndKpa,` with the Save-time fallback from
     *       observedNowOrNull(); observedForPhotoOrNull returns
     *       `StdMoment.photoKpa(captureHoldState(), stdCountEndPhotoKpa,`;
     *   (d) no Android source assigns `observedKpa = ...observedNowOrNull()` - the value at
     *       Save is never filed directly again; and at least three saves call
     *       fileObservedKpa( (the baseline, the after-reading, the log door).
     */
    static void checkStdMoment(String activity, List<String> android, List<String> violations) {
        String flat = activity.replaceAll("\\s", "");
        int open = flat.indexOf("stdWindowEndsAt=now+STD_PHOTO_WINDOW_MS;");
        if (open < 0) {
            violations.add("SessionActivity.java: invariant 223 found no `stdWindowEndsAt = now + "
                + "STD_PHOTO_WINDOW_MS;` - the count's end moved? Update the check deliberately");
        } else {
            // The block the window is opened in: up to its closing brace.
            int depth = 0, end = flat.length();
            for (int i = open; i < flat.length(); i++) {
                char ch = flat.charAt(i);
                if (ch == '{') depth++;
                else if (ch == '}') { if (depth == 0) { end = i; break; } depth--; }
            }
            String block = flat.substring(open, end);
            if (block.indexOf("stdCountEndKpa=observedNowOrNull();") < 0
                    || block.indexOf("stdCountEndPhotoKpa=PhotoTruth.shutterKpa(") < 0)
                violations.add("SessionActivity.java: invariant 223 - the count's end must record "
                    + "stdCountEndKpa = observedNowOrNull() and stdCountEndPhotoKpa = "
                    + "PhotoTruth.shutterKpa( where it opens the two minutes");
        }
        List<MethodSpan> methods = findAllMethodLikeBodies(activity);
        int resets = 0;
        for (int i = 0; i < methods.size(); i++) {
            MethodSpan m = methods.get(i);
            String b = activity.substring(m.bodyStart, m.bodyEnd).replaceAll("\\s", "");
            if (b.indexOf("stdWindowEndsAt=0;") < 0) continue;
            resets++;
            if (b.indexOf("stdCountEndKpa=null;") < 0 || b.indexOf("stdCountEndPhotoKpa=null;") < 0)
                violations.add("SessionActivity.java: invariant 223 - " + m.name + " at line "
                    + lineOf(activity, m.bodyStart) + " starts a new count but keeps the last "
                    + "count's vacuum (clear stdCountEndKpa and stdCountEndPhotoKpa)");
        }
        if (resets == 0)
            violations.add("SessionActivity.java: invariant 223 found no count reset "
                + "(`stdWindowEndsAt = 0;`) - moved? Update the check deliberately");
        int[] fo = robustBody(activity, "void\\s+fileObservedKpa\\s*\\(");
        if (fo == null) {
            violations.add("SessionActivity.java: invariant 223 names fileObservedKpa but it is gone");
        } else {
            String b = activity.substring(fo[0], fo[1]).replaceAll("\\s", "");
            if (b.indexOf("StdMoment.readingKpa(stdCountEndKpa,") < 0
                    || b.indexOf("StdMoment.readingKpaAt(stdCountEndKpa,") < 0
                    || b.indexOf("observedNowOrNull()") < 0)
                violations.add("SessionActivity.java: invariant 223 - fileObservedKpa at line "
                    + lineOf(activity, fo[0]) + " must file StdMoment.readingKpa(stdCountEndKpa, "
                    + "and readingKpaAt(, with the value at Save as the fallback");
        }
        int[] fp = robustBody(activity, "Double\\s+observedForPhotoOrNull\\s*\\(");
        if (fp == null || activity.substring(fp[0], fp[1]).replaceAll("\\s", "")
                .indexOf("StdMoment.photoKpa(captureHoldState(),stdCountEndPhotoKpa,") < 0)
            violations.add("SessionActivity.java: invariant 223 - observedForPhotoOrNull must "
                + "return StdMoment.photoKpa(captureHoldState(), stdCountEndPhotoKpa, ...)");
        int filers = 0;
        Pattern direct = Pattern.compile("observedKpa\\s*=[^;]*observedNowOrNull\\s*\\(");
        Pattern call = Pattern.compile("\\bfileObservedKpa\\s*\\(\\s*[A-Za-z_]");
        for (int i = 0; i < android.size(); i++) {
            String src = android.get(i);
            Matcher d = direct.matcher(src);
            if (d.find())
                violations.add("invariant 223 - `observedKpa = ...observedNowOrNull()` at line "
                    + lineOf(src, d.start()) + " files the vacuum at Save directly - go through "
                    + "fileObservedKpa( (the count's end first)");
            Matcher c = call.matcher(src);
            while (c.find()) filers++;
        }
        // The declaration `void fileObservedKpa(Model.Reading r)` is one match too.
        if (filers < 4)
            violations.add("invariant 223 found " + (filers - 1) + " save(s) calling "
                + "fileObservedKpa(, expected at least 3 (the baseline, the after-reading, the "
                + "log door)");
    }

    /** Invariant 223's self-tests. */
    static void stdMomentSelfTests(int[] counts) {
        String act =
              "void armStdHold() {\n"
            + "    stdWindowEndsAt = 0;\n"
            + "    stdCountEndKpa = null;\n"
            + "    stdCountEndPhotoKpa = null;\n"
            + "}\n"
            + "public void run() {\n"
            + "    if (done) {\n"
            + "        if (stdWindowEndsAt == 0) {\n"
            + "            stdWindowEndsAt = now + STD_PHOTO_WINDOW_MS;\n"
            + "            stdCountEndKpa = observedNowOrNull();\n"
            + "            stdCountEndPhotoKpa = PhotoTruth.shutterKpa(lastKpa, lastNoReading,\n"
            + "                lastSampleMonoAt, now, LINK_TIMEOUT_MS);\n"
            + "            toast(x);\n"
            + "        }\n"
            + "    }\n"
            + "}\n"
            + "void fileObservedKpa(Model.Reading r) {\n"
            + "    Double atSave = observedNowOrNull();\n"
            + "    r.observedKpa = StdMoment.readingKpa(stdCountEndKpa, atSave);\n"
            + "    r.observedAt = StdMoment.readingKpaAt(stdCountEndKpa, atSave);\n"
            + "}\n"
            + "Double observedForPhotoOrNull() {\n"
            + "    Double atShutter = PhotoTruth.shutterKpa(a, b, c, d, e);\n"
            + "    return StdMoment.photoKpa(captureHoldState(), stdCountEndPhotoKpa, atShutter);\n"
            + "}\n"
            + "private Model.Reading afterCandidate() { fileObservedKpa(r); return r; }\n";
        String screens =
              "void saveBaseline() { if (standardised) a.fileObservedKpa(reading); }\n"
            + "void saveLog() { a.fileObservedKpa(reading); }\n";
        List<String> v = new ArrayList<String>();
        checkStdMoment(act, Arrays.asList(act, screens), v);
        selfCheck(counts, v.isEmpty(), "INV223: the app's shapes pass (got " + v + ")");
        String[][] bad = {
            { "A", "a count's end that records nothing",
              "            stdCountEndKpa = observedNowOrNull();\n", "" },
            { "A", "a new count that keeps the old vacuum",
              "    stdCountEndKpa = null;\n    stdCountEndPhotoKpa = null;\n", "" },
            { "A", "a reading filed at Save first",
              "StdMoment.readingKpa(stdCountEndKpa, atSave)", "StdMoment.readingKpa(atSave, stdCountEndKpa)" },
            { "A", "a photo at its shutter only",
              "    return StdMoment.photoKpa(captureHoldState(), stdCountEndPhotoKpa, atShutter);\n",
              "    return atShutter;\n" },
            { "S", "a save that files the vacuum at Save directly",
              "void saveLog() { a.fileObservedKpa(reading); }\n",
              "void saveLog() { reading.observedKpa = a.observedNowOrNull(); }\n" },
        };
        for (int i = 0; i < bad.length; i++) {
            boolean s = "S".equals(bad[i][0]);
            String a2 = s ? act : act.replace(bad[i][2], bad[i][3]);
            String s2 = s ? screens.replace(bad[i][2], bad[i][3]) : screens;
            selfCheck(counts, !(a2.equals(act) && s2.equals(screens)),
                "INV223 self-test edit did not apply: " + bad[i][1]);
            List<String> bv = new ArrayList<String>();
            checkStdMoment(a2, Arrays.asList(a2, s2), bv);
            selfCheck(counts, !bv.isEmpty(), "INV223 must reject " + bad[i][1]);
        }
    }

    /* ===================================================================================== *
     *  INVARIANTS 224-227 - THE 0.10 RUN SCREEN (the owner-approved redesign, 2026-09-28).   *
     *  The rules are pure and JUnit pins them (RunScreenRulesTest); these pin that the run   *
     *  screen keeps STOP as it was, that Coming steps cannot reach a pressure or pass a cap, *
     *  that a Hold is always said on the status line, and that no colour setting reaches     *
     *  STOP. Files are read BY NAME: a missing one is a violation, never a silent pass.      *
     * ===================================================================================== */

    /** One file with its comments stripped and its quotes KEPT (224 reads STOP's words). */
    static String runScreenRaw(String dir, String name, List<String> violations)
            throws IOException {
        File f = new File(dir, name);
        if (!f.isFile()) {
            violations.add("invariants 224-227 read " + name + " but it is not under " + dir
                + " - renamed or moved? Update the check deliberately rather than let a "
                + "rename disable it");
            return null;
        }
        return stripComments(new String(Files.readAllBytes(f.toPath()), "UTF-8"));
    }

    static void checkRunScreen010(String dir, List<String> violations) throws IOException {
        String screen = runScreenRaw(dir, "RunScreen.java", violations);
        String act = runScreenRaw(dir, "SessionActivity.java", violations);
        String look = runScreenRaw(dir, "RunLook.java", violations);
        String model = runScreenRaw(dir, "Model.java", violations);
        if (screen != null) checkStopUnchanged(screen, violations);
        if (screen != null && act != null) checkComingStepsNoPressure(screen, act, violations);
        if (screen != null && look != null) checkHoldAlwaysSaid(screen, look, violations);
        if (screen != null && look != null && model != null)
            checkColoursNeverStop(screen, look, model, violations);
    }

    /** Whitespace out, so a reflow does not decide a rule. */
    private static String flat224(String s) { return s.replaceAll("\\s", ""); }

    /**
     * INVARIANT 224: STOP IS UNCHANGED AND ALWAYS ON THE RUN SCREEN. It is built once, in the
     * pinned footer (never the scroll), full width in the app's red with its own words, and it
     * takes STOP's own tap; nothing else on the run screen hides it, disables it, dims it or
     * repaints it.
     */
    static void checkStopUnchanged(String screen, List<String> violations) {
        String f = flat224(screen);
        String make = "Buttonstop=Ui.big(a,a.runFooter,\"STOP·ventnow\",Ui.CRIT);";
        int at = f.indexOf(make);
        if (at < 0 || f.indexOf(make, at + 1) >= 0)
            violations.add("RunScreen.java: invariant 224 - STOP is not built exactly once as "
                + "Ui.big(a, a.runFooter, \"STOP · vent now\", Ui.CRIT) in the pinned footer");
        if (f.indexOf("stop.setOnClickListener(a.newTap(SessionActivity.Tap.STOP));") < 0)
            violations.add("RunScreen.java: invariant 224 - STOP no longer takes STOP's own tap "
                + "(a.new Tap(SessionActivity.Tap.STOP))");
        Matcher m = Pattern.compile("\\bstop\\s*\\.\\s*(set[A-Za-z]+)\\s*\\(").matcher(screen);
        while (m.find()) {
            String call = m.group(1);
            if (call.equals("setOnClickListener")) continue;
            if (call.equals("setTextColor")
                    && screen.startsWith("Look.ON_RED", skipWs(screen, m.end()))) continue;
            violations.add("RunScreen.java: invariant 224 - stop." + call + "( at line "
                + lineOf(screen, m.start()) + " - STOP stays exactly as it is: same place, same "
                + "red, same words, always there");
        }
    }

    private static int skipWs(String s, int i) {
        while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++;
        return i;
    }

    /** The Activity's Coming-steps methods, and the refusal each must ask before it moves
     *  anything. */
    static final String[][] COMING_APPLIES = {
        { "comingSets", "ComingSteps.setsRefusal(" },
        { "comingHold", "ComingSteps.holdRefusal(" },
        { "comingRest", "ComingSteps.restRefusal(" },
        { "comingSkip", "ComingSteps.skipRefusal(" },
        // 0.10 final: a later block's drop, a later ramp's steps, and undo.
        { "comingDrop", "ComingSteps.dropRefusal(" },
        { "comingDropTime", "ComingSteps.dropTimeRefusal(" },
        { "comingRampSteps", "ComingSteps.rampStepsRefusal(" },
        { "comingRampStepTime", "ComingSteps.rampStepTimeRefusal(" },
        { "comingUndo", "ComingSteps.addRefusal(" },
    };
    /** What no Coming-steps road may do: write a pressure, or reach the pump but through the
     *  table rewrite every edit uses. */
    static final String[] COMING_NEVER = {
        ".up=", ".lo=", "writePull(", "applyOverride(", "sendOverridePreset(", "Proto.",
        "carryUp=", "carryLo=", "applyRoutineOffset(", "nudgeOverride(", "uploadBatch("
    };

    /**
     * INVARIANT 225: COMING STEPS CANNOT RAISE PRESSURE OR PASS A CAP.
     *   (a) comingSets / comingHold / comingRest / comingSkip, comingRetimeRunning and
     *       extendInsertedRest exist, and none of them writes a pull or a drop (up/lo,
     *       writePull, the carry), sends an override, runs the offset, or touches the wire
     *       except through rewriteTableKeepingCountdown;
     *   (b) each apply asks its ComingSteps refusal before it changes a duration, a hold, the
     *       plan or the table - the rules that keep the two-hour stop, the set advisory and
     *       the hold/rest ranges - and an undone skip or a longer inserted rest asks
     *       ComingSteps.addRefusal( (the two-hour stop) first;
     *   (c) the sheet's ComingAct reaches the plan only through those methods (and the rest's
     *       own end), and has no pressure control of its own.
     */
    static void checkComingStepsNoPressure(String screen, String act, List<String> violations) {
        String[] all = { "comingSets", "comingHold", "comingRest", "comingSkip",
                         "comingRetimeRunning", "extendInsertedRest", "comingDrop",
                         "comingDropTime", "comingRampSteps", "comingRampStepTime", "comingUndo",
                         "comingUndoAll" };
        for (int i = 0; i < all.length; i++) {
            int[] b = robustBody(act, "(?:String|boolean|void)\\s+" + all[i] + "\\s*\\(");
            if (b == null) {
                violations.add("SessionActivity.java: invariant 225 names " + all[i]
                    + " but it is gone - renamed? Update the check deliberately");
                continue;
            }
            String body = flat224(act.substring(b[0], b[1]));
            for (int k = 0; k < COMING_NEVER.length; k++)
                if (body.indexOf(COMING_NEVER[k]) >= 0)
                    violations.add("SessionActivity.java: invariant 225 - " + all[i] + " does "
                        + COMING_NEVER[k] + " - Coming steps never writes a pressure or reaches "
                        + "the pump but through the table rewrite every edit uses");
        }
        for (int i = 0; i < COMING_APPLIES.length; i++) {
            int[] b = robustBody(act, "String\\s+" + COMING_APPLIES[i][0] + "\\s*\\(");
            if (b == null) continue;
            String body = flat224(act.substring(b[0], b[1]));
            int ask = body.indexOf(COMING_APPLIES[i][1]);
            int move = firstOf(body, "setPresetDuration(", "comingRetimeRunning(",
                "removeStage(", "plan.addAll(", "rewriteTableKeepingCountdown(", ".uh=",
                "ComingSteps.applyDrop(", "ComingSteps.applyDropTime(", "ComingSteps.respreadRamp(",
                "ComingSteps.setRampStepTime(", "ComingSteps.setRampCycles(",
                "ComingSteps.restoreBlock(", "comingRewrite(");
            if (ask < 0 || (move >= 0 && move < ask))
                violations.add("SessionActivity.java: invariant 225 - " + COMING_APPLIES[i][0]
                    + " changes the run before it asks " + COMING_APPLIES[i][1] + ") - the caps "
                    + "live there");
        }
        int[] sk = robustBody(act, "String\\s+comingSkip\\s*\\(");
        if (sk != null) {
            String body = flat224(act.substring(sk[0], sk[1]));
            int ask = body.indexOf("ComingSteps.addRefusal(");
            int put = body.indexOf("plan.addAll(");
            if (ask < 0 || (put >= 0 && put < ask))
                violations.add("SessionActivity.java: invariant 225 - an undone skip puts steps "
                    + "back before asking ComingSteps.addRefusal( (the two-hour stop)");
        }
        int[] ex = robustBody(act, "String\\s+extendInsertedRest\\s*\\(");
        if (ex != null) {
            String body = flat224(act.substring(ex[0], ex[1]));
            int ask = body.indexOf("ComingSteps.addRefusal(");
            int move = body.indexOf("restNowEndAt+=");
            if (ask < 0 || (move >= 0 && move < ask))
                violations.add("SessionActivity.java: invariant 225 - extendInsertedRest moves "
                    + "the rest's end before asking ComingSteps.addRefusal(");
        }
        int[] ca = robustBody(screen, "class\\s+ComingAct\\b");
        if (ca == null) {
            violations.add("RunScreen.java: invariant 225 names ComingAct but it is gone");
        } else {
            String body = flat224(screen.substring(ca[0], ca[1]));
            for (int k = 0; k < COMING_NEVER.length; k++)
                if (body.indexOf(COMING_NEVER[k]) >= 0)
                    violations.add("RunScreen.java: invariant 225 - ComingAct does "
                        + COMING_NEVER[k] + " - the sheet has no pressure control");
            String[] roads = { "a.comingSets(", "a.comingHold(", "a.comingRest(", "a.comingSkip(" };
            for (int k = 0; k < roads.length; k++)
                if (body.indexOf(roads[k]) < 0)
                    violations.add("RunScreen.java: invariant 225 - ComingAct no longer goes "
                        + "through " + roads[k] + ")");
        }
    }

    private static int firstOf(String s, String... needles) {
        int best = -1;
        for (int i = 0; i < needles.length; i++) {
            int at = s.indexOf(needles[i]);
            if (at >= 0 && (best < 0 || at < best)) best = at;
        }
        return best;
    }

    /**
     * INVARIANT 226: A HOLD IS ALWAYS SAID ON THE STATUS LINE. RunLook.statusLeft answers a
     * hold before anything else; the run screen hands it `a.holding` and writes what it says
     * on the status line every tick; and a HOLD takes its colour whether or not the run is
     * coloured, so a held run can never read as a running one.
     */
    static void checkHoldAlwaysSaid(String screen, String look, List<String> violations) {
        int[] sl = robustBody(look, "String\\s+statusLeft\\s*\\(");
        if (sl == null) {
            violations.add("RunLook.java: invariant 226 names statusLeft but it is gone");
        } else {
            String body = flat224(look.substring(sl[0], sl[1]));
            int hold = body.indexOf("if(n.holding)return");
            int firstReturn = body.indexOf("return");
            int nullGuard = body.indexOf("if(n==null)return");
            int next = nullGuard >= 0 ? body.indexOf("return", nullGuard + 17) : firstReturn;
            if (hold < 0 || hold > next)
                violations.add("RunLook.java: invariant 226 - statusLeft no longer answers a "
                    + "hold first");
        }
        int[] pt = robustBody(screen, "void\\s+paintRunTop\\s*\\(");
        if (pt == null) {
            violations.add("RunScreen.java: invariant 226 names paintRunTop but it is gone");
        } else {
            String body = flat224(screen.substring(pt[0], pt[1]));
            if (body.indexOf("n.holding=a.holding;") < 0
                    || body.indexOf("a.runStatusL.setText(RunLook.statusLeft(n));") < 0)
                violations.add("RunScreen.java: invariant 226 - the status line is not written "
                    + "from RunLook.statusLeft with the run's own `holding`");
        }
        int[] rc = robustBody(screen, "int\\s+runColour\\s*\\(");
        if (rc == null || flat224(screen.substring(rc[0], rc[1]))
                .indexOf("a.model.runColourOn||kind==RunLook.HOLD") < 0)
            violations.add("RunScreen.java: invariant 226 - runColour no longer colours a HOLD "
                + "whatever the setting");
        int[] rf = robustBody(screen, "void\\s+refreshRunScreen\\s*\\(");
        if (rf == null || flat224(screen.substring(rf[0], rf[1])).indexOf("paintRunTop(") < 0)
            violations.add("RunScreen.java: invariant 226 - refreshRunScreen no longer paints the "
                + "status line (paintRunTop)");
    }

    /**
     * INVARIANT 227: NO COLOUR SETTING REACHES STOP. RunLook has no STOP kind and names STOP's
     * red as the app's own (Look.CRITICAL); every colour is refused near it (rejectWhy), and a
     * stored set is taken only through RunLook.sanitize( - so a file cannot bring one in; and
     * the run screen never hands a run colour to STOP (invariant 224 holds STOP's own calls).
     */
    static void checkColoursNeverStop(String screen, String look, String model,
                                      List<String> violations) {
        String lf = flat224(look);
        if (lf.indexOf("publicstaticfinalintSTOP=Look.CRITICAL;") < 0)
            violations.add("RunLook.java: invariant 227 - STOP's red is not Look.CRITICAL");
        Matcher nm = Pattern.compile("NAMES\\s*=\\s*\\{([^}]*)\\}").matcher(look);
        if (!nm.find() || nm.group(1).toUpperCase(java.util.Locale.US).indexOf("STOP") >= 0)
            violations.add("RunLook.java: invariant 227 - a step kind is named STOP, or the "
                + "kinds' names are gone");
        int[] rj = robustBody(look, "String\\s+rejectWhy\\s*\\(");
        if (rj == null || flat224(look.substring(rj[0], rj[1]))
                .indexOf("deltaE(candidate,STOP)<MIN_FROM_STOP") < 0)
            violations.add("RunLook.java: invariant 227 - rejectWhy no longer refuses a colour "
                + "near STOP red");
        if (flat224(model).indexOf("m.runColours=RunLook.sanitize(") < 0)
            violations.add("Model.java: invariant 227 - the stored run colours are not loaded "
                + "through RunLook.sanitize(");
        Matcher w = Pattern.compile("\\bstop\\b[^;]*runColour").matcher(screen);
        if (w.find())
            violations.add("RunScreen.java: invariant 227 - a run colour reaches STOP at line "
                + lineOf(screen, w.start()));
    }

