    /* ===================================================================================== *
     *  INVARIANTS 228-231 - THE 0.10 FINAL RUN SCREEN (the owner-approved mock, 2026-09-28). *
     *  The − / + strip is the one place the step playing changes, and it reaches the pump by *
     *  the live edit's own road; nothing else on the page edits the step playing and Pause    *
     *  is the first button; Coming steps edits only later steps and holds the drop under the  *
     *  floor; where the strip sits is a stored setting and nothing else. The rules are pure   *
     *  and JUnit pins them (QuickAdjustTest, RunScreenRulesTest); these pin the wiring.       *
     * ===================================================================================== */

    static void checkRunScreenFinal(String dir, List<String> violations) throws IOException {
        String screen = runScreenRaw(dir, "RunScreen.java", violations);
        String act = runScreenRaw(dir, "SessionActivity.java", violations);
        String cs = runScreenRaw(dir, "ComingSteps.java", violations);
        String model = runScreenRaw(dir, "Model.java", violations);
        if (screen != null && act != null) checkStripOneRoad(screen, act, violations);
        if (screen != null) checkOnePlacePerJob(screen, violations);
        if (act != null && cs != null) checkComingLaterOnly(act, cs, violations);
        if (screen != null && model != null) checkStripWhere(screen, model, violations);
        if (act != null) checkSetClockTold(act, violations);
        if (act != null) checkSetupHeader(act, violations);
        if (screen != null && act != null) checkCycleRule(screen, act, violations);
        String re = runScreenRaw(dir, "RunEdit.java", violations);
        String ss = runScreenRaw(dir, "SetShift.java", violations);
        if (act != null && re != null && ss != null && cs != null)
            checkDropFloor(act, re, ss, cs, violations);
    }

    /**
     * INVARIANT 231(e): NO COMMANDED PRESET EVER GETS A DROP PAST max(10 kPa, ITS PLANNED DROP)
     * (owner report from a real pump: "Drop to −7.1 inHg" on a ramp step). The build stamps each
     * step's highest drop (RunEdit.asBuilt: p.loMax = max(DROP_FLOOR_KPA, lo)); every road that
     * writes a later step's drop holds it there (RunEdit.capDrop): SetShift's write, the ramp's
     * Reshape (reshapeRemaining) and step count (resizeRemaining), Coming steps' drop and
     * re-spread; and the wire does too - uploadBatch, the adjustment's write (applyOverride with
     * capToRemaining) and the carry the pump takes (commitEdit).
     */
    static void checkDropFloor(String act, String re, String ss, String cs, List<String> violations) {
        String[][] must = {
            { "RunEdit.java", "Model.Preset\\s+asBuilt\\s*\\(", "asBuilt", "p.loMax=Math.max(DROP_FLOOR_KPA," },
            { "RunEdit.java", "int\\s+reshapeRemaining\\s*\\(", "reshapeRemaining", "capDrop(p," },
            { "RunEdit.java", "int\\s+resizeRemaining\\s*\\(", "resizeRemaining", "capDrop(p," },
            { "SetShift.java", "void\\s+write\\s*\\(", "write", "RunEdit.capDrop(p," },
            { "ComingSteps.java", "int\\s+respreadRamp\\s*\\(", "respreadRamp", "RunEdit.capDrop(p," },
            { "ComingSteps.java", "void\\s+applyDrop\\s*\\(", "applyDrop", "RunEdit.capDrop(p," },
            { "SessionActivity.java", "void\\s+uploadBatch\\s*\\(", "uploadBatch", "RunEdit.capDrop(p,p.lo)" },
            { "SessionActivity.java", "boolean\\s+applyOverride\\s*\\([^)]*boolean\\s+capToRemaining\\s*\\)",
              "applyOverride(..., capToRemaining)", "if(capToRemaining)lo=RunEdit.capDrop(p,lo);" },
            { "SessionActivity.java", "void\\s+commitEdit\\s*\\(", "commitEdit",
              "carryLo=RunEdit.clampLower(RunEdit.capDrop(" },
        };
        // (f) "+ step" / "− step" (the ramp playing): the pump's nine steps and the two-hour stop
        // asked before a step is added, a pause before the table is written again.
        String[][] steps = { { "addRampStep", "RunEdit.addStepRefusal(", "RunEdit.addRampStep(" },
                             { "removeAddedRampStep", "RunEdit.removeStepRefusal(", "RunEdit.removeAddedRampStep(" } };
        for (int i = 0; i < steps.length; i++) {
            String b = body228(act, "String\\s+" + steps[i][0] + "\\s*\\(", "SessionActivity.java",
                steps[i][0], violations);
            if (b == null) continue;
            int ask = b.indexOf(steps[i][1]), go = b.indexOf(steps[i][2]),
                hold = b.indexOf("holdMayBeUp()"), table = b.indexOf("rewriteTableKeepingCountdown(");
            if (ask < 0 || go < 0 || go < ask || hold < 0 || table < 0 || table < hold)
                violations.add("SessionActivity.java: invariant 231(f) - " + steps[i][0] + " no longer "
                    + "asks " + steps[i][1] + ") before it changes the ramp, or a pause before it "
                    + "writes the table again");
        }
        for (int i = 0; i < must.length; i++) {
            String src = "RunEdit.java".equals(must[i][0]) ? re : "SetShift.java".equals(must[i][0]) ? ss
                       : "ComingSteps.java".equals(must[i][0]) ? cs : act;
            String b = body228(src, must[i][1], must[i][0], must[i][2], violations);
            if (b != null && b.indexOf(must[i][3]) < 0)
                violations.add(must[i][0] + ": invariant 231(e) - " + must[i][2] + " no longer holds a "
                    + "drop to the step's highest (" + must[i][3] + ") - a drop could pass the 10 kPa "
                    + "floor and the cuff barely release");
        }
    }

    /** Invariant 231(e)'s self-test. */
    static void dropFloorSelfTests(int[] counts) {
        String re = "public static Model.Preset asBuilt(Model.Preset p) { p.loMax = Math.max(DROP_FLOOR_KPA, Math.max(0, p.lo)); return p; }\n"
            + "public static int reshapeRemaining(List<Model.Preset> plan, int i) { p.lo = clampLower(capDrop(p, x), up); return 0; }\n"
            + "public static int resizeRemaining(List<Model.Preset> plan, int i) { p.lo = clampLower(capDrop(p, x), up); return 0; }\n";
        String ss = "private static void write(Model.Preset p, int[] b) { p.lo = RunEdit.clampLower(RunEdit.capDrop(p, lo), p.up); }\n";
        String cs = "public static int respreadRamp(List<Model.Preset> plan, int f) { p.lo = RunEdit.clampLower(RunEdit.capDrop(p, x), p.up); return 0; }\n"
            + "public static void applyDrop(Model.Preset p, int lo) { p.lo = RunEdit.clampLower(RunEdit.capDrop(p, lo), p.up); }\n";
        String act = "private void uploadBatch(int from) { int lo = RunEdit.clampLower(RunEdit.capDrop(p, p.lo), up); }\n"
            + "boolean applyOverride(int up, int lo, int uh, int lh, int sp, String why, boolean capToRemaining) {"
            + " if (capToRemaining) lo = RunEdit.capDrop(p, lo); return true; }\n"
            + "private void commitEdit(PendingChange.Change c) { carryLo = RunEdit.clampLower(RunEdit.capDrop(p, lo), carryUp); }\n"
            + "String addRampStep() { if (holdMayBeUp()) return x; String why = RunEdit.addStepRefusal(plan, planIdx);"
            + " int at = RunEdit.addRampStep(plan, planIdx, c); rewriteTableKeepingCountdown(planIdx + 1); return y; }\n"
            + "String removeAddedRampStep() { if (holdMayBeUp()) return x; String why = RunEdit.removeStepRefusal(plan, planIdx);"
            + " RunEdit.removeAddedRampStep(plan, planIdx); rewriteTableKeepingCountdown(planIdx + 1); return y; }\n";
        List<String> v = new ArrayList<String>();
        checkDropFloor(act, re, ss, cs, v);
        selfCheck(counts, v.isEmpty(), "INV231e: the app's shapes pass (got " + v + ")");
        String[][] bad = {
            { "R", "a build without its highest drop", "p.loMax = Math.max(DROP_FLOOR_KPA, Math.max(0, p.lo)); ", "" },
            { "R", "a reshape spreading a raised drop", "{ p.lo = clampLower(capDrop(p, x), up); return 0; }\npublic static int resize",
              "{ p.lo = clampLower(x, up); return 0; }\npublic static int resize" },
            { "S", "a shift moving drops past the floor", "RunEdit.capDrop(p, lo)", "lo" },
            { "C", "Coming steps raising a drop", "p.lo = RunEdit.clampLower(RunEdit.capDrop(p, lo), p.up); }", "p.lo = lo; }" },
            { "A", "the table written past the floor", "RunEdit.capDrop(p, p.lo)", "p.lo" },
            { "A", "an adjustment written past the floor", " if (capToRemaining) lo = RunEdit.capDrop(p, lo);", "" },
            { "A", "a carry past the floor", "carryLo = RunEdit.clampLower(RunEdit.capDrop(p, lo), carryUp);",
              "carryLo = RunEdit.clampLower(lo, carryUp);" },
            { "A", "a step added past the pump's nine", " String why = RunEdit.addStepRefusal(plan, planIdx);", "" },
            { "A", "the table rewritten under a pause", "String removeAddedRampStep() { if (holdMayBeUp()) return x;",
              "String removeAddedRampStep() {" },
        };
        for (int i = 0; i < bad.length; i++) {
            String k = bad[i][0];
            String re2 = "R".equals(k) ? re.replace(bad[i][2], bad[i][3]) : re;
            String ss2 = "S".equals(k) ? ss.replace(bad[i][2], bad[i][3]) : ss;
            String cs2 = "C".equals(k) ? cs.replace(bad[i][2], bad[i][3]) : cs;
            String a2 = "A".equals(k) ? act.replace(bad[i][2], bad[i][3]) : act;
            selfCheck(counts, !(re2.equals(re) && ss2.equals(ss) && cs2.equals(cs) && a2.equals(act)),
                "INV231e self-test edit did not apply: " + bad[i][1]);
            List<String> bv = new ArrayList<String>();
            checkDropFloor(a2, re2, ss2, cs2, bv);
            selfCheck(counts, !bv.isEmpty(), "INV231e must reject " + bad[i][1]);
        }
    }

    /**
     * INVARIANT 231(d): A STEP IS AT LEAST ONE CYCLE, ON EVERY ROAD (owner decision, 0.10). In
     * a ramp's step and the warm-up, a hold or drop time that would make the cycle longer than
     * the step is refused, and the step's length never goes under one cycle:
     *   - the strip asks a.cycleRefusalNow( (stripRefusal), and the adjust sheet's road -
     *     applyOverride - asks cycleRefusalNow( before anything is sent (sendOverridePreset);
     *   - quickRampStep and quickWarm ask QuickAdjust.stepLengthRefusal( before they re-time
     *     (comingRetimeRunning);
     *   - the sheet's Reshape asks QuickAdjust.reshapeCycleRefusal( before RunEdit.reshapeRemaining(;
     *   - Coming steps' time per step passes the ramp's cycle (ComingSteps.rampCycleSec().
     * A ONE-CYCLE STEP IS A SET: commitEdit reads the later one-cycle steps
     * (QuickAdjust.oneCycleLater) BEFORE the scope shifts them, and the step playing runs whole
     * from every restart through the one rule - keepSetsWhole takes it as one set left
     * (oneCycleNow(), `one ? 1 :`), whatever the SetClock counts. The drop floor holds on the sheet's road too:
     * applyOverride asks QuickAdjust.dropRefusal(, and the sheet's drop slider stops at
     * sheetDropCap() (RunEdit.dropCapOf). The ceiling's "flat there" note is said once per ramp
     * (QuickAdjust.rampFlatSaidOnce().
     * NEVER A REPEATED HOLD (HoldCarryOn, owner report from a real pump): applyOverride plans the
     * change (carryOnPlanFor(uh, lh)) before it begins it (liveLink.beginChange); the write
     * carries the hold under way on (holdS = carryOnWire when there is one); and the change in
     * force is carried on - setClockAfterChange returns carryOnInForce(co) before the restart's
     * keepSetsWhole(false).
     */
    static void checkCycleRule(String screen, String act, List<String> violations) {
        String ref = body228(screen, "String\\s+stripRefusal\\s*\\(", "RunScreen.java",
            "stripRefusal", violations);
        if (ref != null && ref.indexOf("a.cycleRefusalNow(") < 0)
            violations.add("RunScreen.java: invariant 231(d) - the strip no longer asks the cycle "
                + "rule (a.cycleRefusalNow) before a longer hold or drop time");
        String ao = body228(act, "boolean\\s+applyOverride\\s*\\(\\s*int\\s+up\\s*,\\s*int\\s+lo\\s*,"
            + "\\s*int\\s+uh\\s*,\\s*int\\s+lh\\s*,\\s*int\\s+sp\\s*,\\s*String\\s+why\\s*\\)",
            "SessionActivity.java", "applyOverride", violations);
        if (ao != null) {
            int ask = ao.indexOf("cycleRefusalNow(uh,lh)"), send = ao.indexOf("applyOverride(");
            if (ask < 0 || (send >= 0 && send < ask))
                violations.add("SessionActivity.java: invariant 231(d) - applyOverride no longer "
                    + "asks the cycle rule (cycleRefusalNow) before it sends");
        }
        String[] lens = { "quickRampStep", "quickWarm" };
        for (int i = 0; i < lens.length; i++) {
            String b = body228(act, "String\\s+" + lens[i] + "\\s*\\(", "SessionActivity.java",
                lens[i], violations);
            if (b == null) continue;
            int ask = b.indexOf("QuickAdjust.stepLengthRefusal("), go = b.indexOf("comingRetimeRunning(");
            if (ask < 0 || go < 0 || go < ask)
                violations.add("SessionActivity.java: invariant 231(d) - " + lens[i] + " re-times "
                    + "before asking the cycle rule (QuickAdjust.stepLengthRefusal)");
        }
        String rs = body228(screen, "void\\s+applyRampReshape\\s*\\(", "RunScreen.java",
            "applyRampReshape", violations);
        if (rs != null) {
            int ask = rs.indexOf("QuickAdjust.reshapeCycleRefusal("), go = rs.indexOf("RunEdit.reshapeRemaining(");
            if (ask < 0 || go < 0 || go < ask)
                violations.add("RunScreen.java: invariant 231(d) - Reshape no longer asks the cycle "
                    + "rule (QuickAdjust.reshapeCycleRefusal) before it rewrites the ramp");
        }
        String ce = body228(act, "void\\s+commitEdit\\s*\\(", "SessionActivity.java", "commitEdit",
            violations);
        if (ce != null) {
            int read = ce.indexOf("QuickAdjust.oneCycleLater("), shift = ce.indexOf("shiftRemainingOfSet(");
            if (read < 0 || shift < 0 || shift < read)
                violations.add("SessionActivity.java: invariant 231(d) - commitEdit no longer reads the "
                    + "later one-cycle steps (QuickAdjust.oneCycleLater) before the scope shifts them");
            String ksw = body228(act, "long\\s+keepSetsWhole\\s*\\(", "SessionActivity.java",
                "keepSetsWhole", violations);
            if (ksw != null && (ksw.indexOf("booleanone=oneCycleNow();") < 0
                    || ksw.indexOf("intleft=one?1:setClock.setsLeft(now);") < 0))
                violations.add("SessionActivity.java: invariant 231(d) - a one-cycle step is no longer "
                    + "kept whole as one set (keepSetsWhole: oneCycleNow(), one set left)");
            // A RESUME CARRIES THE HOLD UNDER WAY ON: the clock carries on before any restart,
            // and both of the Resume's writers write what was left of the hold.
            if (ksw != null) {
                int rco = ksw.indexOf("if(resumed&&resumeCarryOn!=null)"), rres = ksw.indexOf("setClock.resume(");
                if (rco < 0 || rres < 0 || rres < rco)
                    violations.add("SessionActivity.java: invariant 231(d) - a Resume out of a pause "
                        + "no longer carries the hold on (keepSetsWhole: resumeCarryOn first)");
            }
            String[] writers = { "armRoutineSlot", "armCarry" };
            for (int i = 0; i < writers.length; i++) {
                String wb = body228(act, "boolean\\s+" + writers[i] + "\\s*\\(", "SessionActivity.java",
                    writers[i], violations);
                if (wb != null && wb.indexOf("resumeWireUh(kind,") < 0)
                    violations.add("SessionActivity.java: invariant 231(d) - " + writers[i] + " no "
                        + "longer writes what was left of the paused hold on Resume (resumeWireUh)");
            }
            if (ce.indexOf("QuickAdjust.rampFlatSaidOnce(") < 0)
                violations.add("SessionActivity.java: invariant 231(d) - the ceiling's \"flat there\" "
                    + "note is no longer said once per ramp (QuickAdjust.rampFlatSaidOnce)");
        }
        if (ao != null) {
            int plan = ao.indexOf("HoldCarryOn.Planco=carryOnPlanFor(uh,lh);"),
                begin = ao.indexOf("liveLink.beginChange(");
            if (plan < 0 || begin < 0 || begin < plan)
                violations.add("SessionActivity.java: invariant 231(d) - applyOverride no longer plans "
                    + "the change (carryOnPlanFor) before it begins it: the hold under way would be "
                    + "started again from zero");
        }
        String ao7 = body228(act, "boolean\\s+applyOverride\\s*\\([^)]*boolean\\s+capToRemaining\\s*\\)",
            "SessionActivity.java", "applyOverride(..., capToRemaining)", violations);
        if (ao7 != null && ao7.indexOf("carryOnWire>0?carryOnWire:") < 0)
            violations.add("SessionActivity.java: invariant 231(d) - the write no longer carries the "
                + "hold under way on (holdS = carryOnWire)");
        String sca = body228(act, "String\\s+setClockAfterChange\\s*\\(", "SessionActivity.java",
            "setClockAfterChange", violations);
        if (sca != null) {
            int co = sca.indexOf("returncarryOnInForce(co);"), ks = sca.indexOf("keepSetsWhole(false)");
            if (co < 0 || ks < 0 || ks < co)
                violations.add("SessionActivity.java: invariant 231(d) - a change carried on is no "
                    + "longer put in force as carried on (carryOnInForce) before the restart's rule");
        }
        if (ao != null && ao.indexOf("QuickAdjust.dropRefusal(") < 0)
            violations.add("SessionActivity.java: invariant 231(d) - applyOverride no longer holds "
                + "the drop floor (QuickAdjust.dropRefusal)");
        String fo = body228(screen, "void\\s+fillOverrideSheet\\s*\\(", "RunScreen.java",
            "fillOverrideSheet", violations);
        if (fo != null && fo.indexOf("overrideSlider(OvSlide.LO,\"drop\",Model.Fmt.p(a.ovLo),a.ovLo,"
                + "Math.max(1,sheetDropCap())") < 0)
            violations.add("RunScreen.java: invariant 231(d) - the sheet's drop slider no longer stops "
                + "at the strip's floor (sheetDropCap)");
        String ct = body228(act, "String\\s+comingRampStepTime\\s*\\(", "SessionActivity.java",
            "comingRampStepTime", violations);
        if (ct != null && ct.indexOf("ComingSteps.rampCycleSec(") < 0)
            violations.add("SessionActivity.java: invariant 231(d) - Coming steps' time per step "
                + "no longer keeps the ramp's cycle (ComingSteps.rampCycleSec)");
    }

    /** Invariant 231(d)'s self-test. */
    static void cycleRuleSelfTests(int[] counts) {
        String screen =
              "private String stripRefusal(StripNow s, int field, int dir) { no = a.cycleRefusalNow(nu, nl); return no; }\n"
            + "private void applyRampReshape() { String t = QuickAdjust.reshapeCycleRefusal(p, i, 1, 2, 3, 4, n);"
            + " if (t != null) return; int n = RunEdit.reshapeRemaining(p, i); }\n"
            + "private void fillOverrideSheet() { overrideSlider(OvSlide.LO, \"drop\", Model.Fmt.p(a.ovLo), a.ovLo,"
            + " Math.max(1, sheetDropCap())); }\n";
        String act =
              "boolean applyOverride(int up, int lo, int uh, int lh, int sp, String why) {"
            + " HoldCarryOn.Plan co = carryOnPlanFor(uh, lh); int change = liveLink.beginChange(1, 2, t, r, 0);"
            + " String cycle = cycleRefusalNow(uh, lh); if (cycle == null) cycle = QuickAdjust.dropRefusal(a, lo);"
            + " if (cycle != null) return false;"
            + " sent = applyOverride(up, lo, uh, lh, sp, why, true); return sent; }\n"
            + "String quickRampStep(int d) { String under = QuickAdjust.stepLengthRefusal(1, 2, 3, n);"
            + " if (!comingRetimeRunning(d)) return x; return null; }\n"
            + "String quickWarm(int d) { String under = QuickAdjust.stepLengthRefusal(1, 2, 3, n);"
            + " if (!comingRetimeRunning(d)) return x; return null; }\n"
            + "private void commitEdit(PendingChange.Change c) { long[][] laterOne = QuickAdjust.oneCycleLater(plan, i, n);"
            + " shiftRemainingOfSet(occLeft, inForceBefore);"
            + " String flat = QuickAdjust.rampFlatSaidOnce(1, 2, 3, 4); }\n"
            + "boolean applyOverride(int up, int lo, int uh, int lh, int sp, String why, boolean capToRemaining) {"
            + " int holdS = capToRemaining ? (carryOnWire > 0 ? carryOnWire : 1) : uh; return true; }\n"
            + "private String setClockAfterChange(int[] before, boolean rampOcc, int seq) {"
            + " if (carryOnPlan != null) { return carryOnInForce(co); } long move = keepSetsWhole(false); return null; }\n"
            + "private long keepSetsWhole(boolean resumed) { if (resumed && resumeCarryOn != null) return 0L;"
            + " boolean one = oneCycleNow(); int left = one ? 1 : setClock.setsLeft(now);"
            + " if (resumed) setClock.resume(n, c); return 0L; }\n"
            + "private boolean armRoutineSlot(int slot, int kind, String why) { int wire = resumeWireUh(kind, p.uh); return true; }\n"
            + "private boolean armCarry(int kind, String why) { int wire = resumeWireUh(kind, carryUh); return true; }\n"
            + "String comingRampStepTime(int si, int d) { String why = ComingSteps.rampStepTimeRefusal(1, 2, 3, 4,"
            + " ComingSteps.rampCycleSec(plan, f, n)); return null; }\n";
        List<String> v = new ArrayList<String>();
        checkCycleRule(screen, act, v);
        selfCheck(counts, v.isEmpty(), "INV231d: the app's shapes pass (got " + v + ")");
        String[][] bad = {
            { "S", "the strip without the cycle rule", "no = a.cycleRefusalNow(nu, nl); ", "" },
            { "S", "a reshape past the cycle", "String t = QuickAdjust.reshapeCycleRefusal(p, i, 1, 2, 3, 4, n); if (t != null) return; ", "" },
            { "A", "the sheet's road without the cycle rule", " String cycle = cycleRefusalNow(uh, lh);", " String cycle = null;" },
            { "A", "the sheet's road without the drop floor", " if (cycle == null) cycle = QuickAdjust.dropRefusal(a, lo);", "" },
            { "S", "the sheet's drop slider past the floor", "Math.max(1, sheetDropCap())",
              "Math.max(1, a.model.ceilKpa)" },
            { "A", "the later one-cycle steps read after the shift moved them",
              "long[][] laterOne = QuickAdjust.oneCycleLater(plan, i, n); shiftRemainingOfSet(occLeft, inForceBefore);",
              "shiftRemainingOfSet(occLeft, inForceBefore); long[][] laterOne = QuickAdjust.oneCycleLater(plan, i, n);" },
            { "A", "a change begun before it is planned: the hold started again from zero",
              " HoldCarryOn.Plan co = carryOnPlanFor(uh, lh); int change = liveLink.beginChange(1, 2, t, r, 0);",
              " int change = liveLink.beginChange(1, 2, t, r, 0); HoldCarryOn.Plan co = carryOnPlanFor(uh, lh);" },
            { "A", "the full new hold written over the hold under way", "(carryOnWire > 0 ? carryOnWire : 1)", "1" },
            { "A", "a carried-on change put in force as a restart", "{ return carryOnInForce(co); }", "{ }" },
            { "A", "a Resume that starts the paused hold again", "if (resumed && resumeCarryOn != null) return 0L;", "" },
            { "A", "a Resume writing the routine slot's full hold", "int wire = resumeWireUh(kind, p.uh);", "int wire = -1;" },
            { "A", "a one-cycle step not kept whole", "int left = one ? 1 : setClock.setsLeft(now);",
              "int left = setClock.setsLeft(now);" },
            { "A", "the flat note on every change", "QuickAdjust.rampFlatSaidOnce(1, 2, 3, 4)", "QuickAdjust.rampFlatSaid(1, 2)" },
            { "A", "a ramp step shortened under its cycle",
              "String quickRampStep(int d) { String under = QuickAdjust.stepLengthRefusal(1, 2, 3, n);",
              "String quickRampStep(int d) {" },
            { "A", "a warm-up shortened under its cycle",
              "String quickWarm(int d) { String under = QuickAdjust.stepLengthRefusal(1, 2, 3, n);",
              "String quickWarm(int d) {" },
            { "A", "Coming steps' time per step under the cycle", " ComingSteps.rampCycleSec(plan, f, n)", " 0" },
        };
        for (int i = 0; i < bad.length; i++) {
            String s2 = "S".equals(bad[i][0]) ? screen.replace(bad[i][2], bad[i][3]) : screen;
            String a2 = "A".equals(bad[i][0]) ? act.replace(bad[i][2], bad[i][3]) : act;
            selfCheck(counts, !(s2.equals(screen) && a2.equals(act)),
                "INV231d self-test edit did not apply: " + bad[i][1]);
            List<String> bv = new ArrayList<String>();
            checkCycleRule(s2, a2, bv);
            selfCheck(counts, !bv.isEmpty(), "INV231d must reject " + bad[i][1]);
        }
    }

    /** Invariant 229(e), the engine's half: where the pump's cycle begins again, the SetClock
     *  is told, through ONE rule (keepSetsWhole: every set runs whole - the device check of
     *  772e1e7 found a Resume cutting the last set short); the block's end moves only inside
     *  the two-hour stop. */
    static void checkSetClockTold(String act, List<String> violations) {
        String[][] told = {
            { "void\\s+commitEdit\\s*\\(", "commitEdit", "setClockAfterChange(" },
            { "String\\s+setClockAfterChange\\s*\\(", "setClockAfterChange", "keepSetsWhole(false)" },
            { "boolean\\s+confirmHold\\s*\\(", "confirmHold", "setClock.pause(" },
            { "void\\s+resumeRepArmedHere\\s*\\(", "resumeRepArmedHere", "keepSetsWhole(true)" },
            { "boolean\\s+armRoutineSlot\\s*\\(", "armRoutineSlot", "keepSetsWhole(" },
            { "void\\s+playPreset\\s*\\(", "playPreset", "startSetClock(" },
        };
        for (int i = 0; i < told.length; i++) {
            String b = body228(act, told[i][0], "SessionActivity.java", told[i][1], violations);
            if (b != null && b.indexOf(told[i][2]) < 0)
                violations.add("SessionActivity.java: invariant 229 - " + told[i][1] + " no longer "
                    + "tells the set count (" + told[i][2] + ") - the count would restart or drift");
        }
        String sc = body228(act, "long\\s+keepSetsWhole\\s*\\(", "SessionActivity.java",
            "keepSetsWhole", violations);
        if (sc != null) {
            int cap = sc.indexOf("ComingSteps.addRefusal("), move = sc.indexOf("comingRetimeRunning(");
            if (cap < 0 || move < 0 || move < cap || sc.indexOf("setClock.restart(") < 0
                    || sc.indexOf("setClock.resume(") < 0 || sc.indexOf("SetClock.retimeMs(") < 0)
                violations.add("SessionActivity.java: invariant 229 - keepSetsWhole moves the "
                    + "block's end without asking the two-hour stop first, or no longer keeps the "
                    + "set under way (setClock.restart( / .resume() by SetClock.retimeMs(");
        }
    }

    /** A method's body with its whitespace out, or null (and a violation) when it is gone. */
    private static String body228(String src, String sig, String file, String name,
                                  List<String> violations) {
        int[] b = robustBody(src, sig);
        if (b == null) {
            violations.add(file + ": invariants 228-231 name " + name + " but it is gone - "
                + "renamed? Update the check deliberately rather than let a rename disable it");
            return null;
        }
        return flat224(src.substring(b[0], b[1]));
    }

    /** The lengths the strip changes, and what each must ask before it moves anything. */
    static final String[] STRIP_LENGTHS = { "quickRest", "quickRampStep", "quickWarm" };
    static final String[] STRIP_LENGTH_MOVES = { "comingRetimeRunning(", "restNowEndAt+=",
        "setPresetDuration(" };

    /**
     * INVARIANT 228: THE − / + STRIP HAS ONE ROAD, AND IS NEVER REBUILT ON THE TICK.
     *   (a) buildStrip is called once, from showRun; refreshRunScreen and paintStrip rebuild
     *       nothing (no removeAllViews, no buildStrip, no new key or cell) - a tick never takes
     *       a key out from under a finger;
     *   (b) a tap asks stripRefusal (the approved ranges) before stripApply; stripApply reaches
     *       a set's figures only through nudgeBy and a length only through a.quickRest /
     *       a.quickRampStep / a.quickWarm, and writes no pressure and sends nothing itself;
     *   (c) nudgeBy asks canCommandNow() first and goes through liveEdit.tapBy( and then
     *       overrideChanged( - the live edit's pending target and debounced settle, so every
     *       safety rule applyOverride has (the ceiling, nothing over a pause, nothing while the
     *       pump has not answered) holds and the countdown is untouched;
     *   (d) each length asks QuickAdjust.refusal( and ComingSteps.addRefusal( (the two-hour
     *       stop) before it moves the clock, writes no pressure and sends no override itself;
     *       quickRampStep and quickWarm refuse under a pause (quickRefusal, holdMayBeUp()).
     */
    static void checkStripOneRoad(String screen, String act, List<String> violations) {
        String f = flat224(screen);
        int calls = 0, at = -1;
        while ((at = f.indexOf("buildStrip()", at + 1)) >= 0) calls++;
        String show = body228(screen, "void\\s+showRun\\s*\\(", "RunScreen.java", "showRun", violations);
        if (calls != 2 || show == null || show.indexOf("buildStrip()") < 0)
            violations.add("RunScreen.java: invariant 228 - the strip is not built exactly once, "
                + "in showRun (buildStrip)");
        String[] noBuild = { "removeAllViews(", "buildStrip(", "newButton(", "stripCell(", "stripKey(" };
        String rr = body228(screen, "void\\s+refreshRunScreen\\s*\\(", "RunScreen.java",
            "refreshRunScreen", violations);
        Matcher pm = Pattern.compile("void\\s+paintStrip\\s*\\(").matcher(screen);
        List<String> paints = new ArrayList<String>();
        while (pm.find()) {
            int[] b = robustBody(screen.substring(pm.start()), "void\\s+paintStrip\\s*\\(");
            if (b != null) paints.add(flat224(screen.substring(pm.start() + b[0], pm.start() + b[1])));
        }
        if (paints.isEmpty())
            violations.add("RunScreen.java: invariant 228 names paintStrip but it is gone");
        if (rr != null) paints.add(rr);
        for (int i = 0; i < paints.size(); i++)
            for (int k = 0; k < noBuild.length; k++)
                if (paints.get(i).indexOf(noBuild[k]) >= 0)
                    violations.add("RunScreen.java: invariant 228 - the tick (refreshRunScreen / "
                        + "paintStrip) does " + noBuild[k] + ") - the strip is built once and only "
                        + "repainted, so a tick never takes a key out from under a finger");
        String step = body228(screen, "boolean\\s+stripStep\\s*\\(", "RunScreen.java", "stripStep",
            violations);
        if (step != null) {
            int ask = step.indexOf("stripRefusal("), go = step.indexOf("stripApply(");
            if (ask < 0 || go < 0 || go < ask)
                violations.add("RunScreen.java: invariant 228 - stripStep does not ask stripRefusal "
                    + "(the approved ranges) before stripApply");
        }
        String apply = body228(screen, "String\\s+stripApply\\s*\\(", "RunScreen.java", "stripApply",
            violations);
        if (apply != null) {
            String[] must = { "nudgeBy(LiveEdit.UP,", "nudgeBy(LiveEdit.UH,", "nudgeBy(LiveEdit.LO,",
                "nudgeBy(LiveEdit.LH,", "a.quickRest(", "a.quickRampStep(", "a.quickWarm(" };
            for (int k = 0; k < must.length; k++)
                if (apply.indexOf(must[k]) < 0)
                    violations.add("RunScreen.java: invariant 228 - stripApply no longer goes "
                        + "through " + must[k] + ")");
            for (int k = 0; k < COMING_NEVER.length; k++)
                if (apply.indexOf(COMING_NEVER[k]) >= 0 && !COMING_NEVER[k].equals("nudgeOverride("))
                    violations.add("RunScreen.java: invariant 228 - stripApply does "
                        + COMING_NEVER[k] + " - the strip reaches the pump only by the live edit's road");
        }
        String nb = body228(screen, "String\\s+nudgeBy\\s*\\(", "RunScreen.java", "nudgeBy", violations);
        if (nb != null) {
            int can = nb.indexOf("a.canCommandNow()"), tap = nb.indexOf("liveEdit.tapBy(");
            int settle = nb.indexOf("overrideChanged(");
            if (can < 0 || tap < 0 || settle < 0 || tap < can || settle < tap)
                violations.add("RunScreen.java: invariant 228 - nudgeBy does not ask canCommandNow() "
                    + "and then go through liveEdit.tapBy( and overrideChanged( (the live edit's "
                    + "pending target and settle)");
            for (int k = 0; k < COMING_NEVER.length; k++)
                if (nb.indexOf(COMING_NEVER[k]) >= 0)
                    violations.add("RunScreen.java: invariant 228 - nudgeBy does " + COMING_NEVER[k]
                        + " - it only dials the target; the settle sends it");
        }
        for (int i = 0; i < STRIP_LENGTHS.length; i++) {
            String b = body228(act, "String\\s+" + STRIP_LENGTHS[i] + "\\s*\\(", "SessionActivity.java",
                STRIP_LENGTHS[i], violations);
            if (b == null) continue;
            int move = firstOf(b, STRIP_LENGTH_MOVES);
            int range = b.indexOf("QuickAdjust.refusal("), cap = b.indexOf("ComingSteps.addRefusal(");
            if (range < 0 || cap < 0 || (move >= 0 && (move < range || move < cap)))
                violations.add("SessionActivity.java: invariant 228 - " + STRIP_LENGTHS[i]
                    + " moves the clock before it asks QuickAdjust.refusal( and "
                    + "ComingSteps.addRefusal( (the approved range and the two-hour stop)");
            for (int k = 0; k < COMING_NEVER.length; k++)
                if (b.indexOf(COMING_NEVER[k]) >= 0)
                    violations.add("SessionActivity.java: invariant 228 - " + STRIP_LENGTHS[i]
                        + " does " + COMING_NEVER[k] + " - a length is the app's own clock");
            if (i > 0 && (b.indexOf("quickRefusal()") < 0
                    || (move >= 0 && b.indexOf("quickRefusal()") > move)))
                violations.add("SessionActivity.java: invariant 228 - " + STRIP_LENGTHS[i]
                    + " does not refuse under a pause (quickRefusal) before it moves the clock");
        }
        String qr = body228(act, "String\\s+quickRefusal\\s*\\(", "SessionActivity.java",
            "quickRefusal", violations);
        if (qr != null && qr.indexOf("holdMayBeUp()") < 0)
            violations.add("SessionActivity.java: invariant 228 - quickRefusal no longer refuses "
                + "under a pause (holdMayBeUp())");
    }

    /**
     * INVARIANT 229: ONE PLACE PER JOB, AND PAUSE FIRST.
     *   (a) a typed figure is opened only from the adjust sheet (every new OvTypeTap( is the
     *       sheet's, `true`) - nothing on the run screen's page but the strip edits the step
     *       playing, and the NOW card's "SET ›" row is gone;
     *   (b) the footer's buttons are built Pause first, then Skip, +30 s and Rest;
     *   (c) Pause's tap releases a pause before it asks anything else (a resume is never
     *       refused), and refuses in a rest with its own words;
     *   (d) the status line is handed the ramp's step (paintRunTop sets n.ramp from
     *       RunEdit.stepOfSet), so a ramp reads "RAMP · STEP k OF n", never "WORK";
     *   (e) the set count of the step playing is the engine's SetClock (setOf goes through
     *       clockSet, which reads a.setClock) - and the engine tells it where the pump's cycle
     *       begins again: a step armed (startSetClock), a change in force (commitEdit ->
     *       setClockAfterChange), a pause (confirmHold -> setClock.pause) and a resume
     *       (resumeRepArmedHere -> setClock.resume). A change of cycle moves the block's end
     *       only after the two-hour stop is asked (ComingSteps.addRefusal( before
     *       comingRetimeRunning(). The device check found the count restarting at 1 and the
     *       total shrinking on every live change; the owner's rule is the mock's reanchor():
     *       the count stays, the set under way keeps its number, a longer cycle moves the end.
     */
    static void checkOnePlacePerJob(String screen, List<String> violations) {
        String f = flat224(screen);
        Matcher t = Pattern.compile("new\\s+OvTypeTap\\s*\\(([^;]*?)\\)\\s*\\)").matcher(screen);
        while (t.find())
            if (!flat224(t.group(1)).endsWith(",true"))
                violations.add("RunScreen.java: invariant 229 - a typed figure is opened from outside "
                    + "the adjust sheet at line " + lineOf(screen, t.start()) + " - the strip is the "
                    + "one place on the page that edits the step playing");
        if (f.indexOf("\"SET›\"") >= 0)
            violations.add("RunScreen.java: invariant 229 - the NOW card's \"SET ›\" row is back");
        String show = body228(screen, "void\\s+showRun\\s*\\(", "RunScreen.java", "showRun", violations);
        if (show != null) {
            int p = show.indexOf("a.holdBtn=a.timerControl(ctl,\"Pause\"");
            int s = show.indexOf("a.skipBtn=a.timerControl(ctl,");
            int e = show.indexOf("a.extendBtn=a.timerControl(ctl,");
            int r = show.indexOf("a.restBtn=a.timerControl(ctl,");
            if (p < 0 || s < p || e < s || r < e)
                violations.add("RunScreen.java: invariant 229 - the footer is not built Pause first "
                    + "(Pause, Skip, +30 s, Rest)");
        }
        String top = body228(screen, "void\\s+paintRunTop\\s*\\(", "RunScreen.java", "paintRunTop",
            violations);
        if (top != null && (top.indexOf("n.ramp=true;") < 0 || top.indexOf("RunEdit.stepOfSet(") < 0
                || top.indexOf("n.stepK=") < 0 || top.indexOf("n.stepN=") < 0))
            violations.add("RunScreen.java: invariant 229 - paintRunTop no longer hands the status "
                + "line the ramp's step (n.ramp, RunEdit.stepOfSet) - a ramp would read WORK");
        String so = body228(screen, "int\\[\\]\\s+setOf\\s*\\(", "RunScreen.java", "setOf", violations);
        String ck = body228(screen, "int\\[\\]\\s+clockSet\\s*\\(", "RunScreen.java", "clockSet",
            violations);
        if (so != null && so.indexOf("clockSet(") < 0)
            violations.add("RunScreen.java: invariant 229 - setOf no longer counts the step playing "
                + "by the SetClock (clockSet)");
        if (ck != null && (ck.indexOf("a.setClock.set(") < 0 || ck.indexOf("a.setClock.sets()") < 0))
            violations.add("RunScreen.java: invariant 229 - clockSet no longer reads the engine's "
                + "SetClock (a.setClock.set(, a.setClock.sets())");
        String hold = body228(screen, "class\\s+HoldTap\\b", "RunScreen.java", "HoldTap", violations);
        if (hold != null) {
            int rel = hold.indexOf("if(a.holding){a.exitHold(true);return;}");
            int rest = hold.indexOf("inRest(");
            int can = hold.indexOf("a.canCommandNow()");
            if (rel < 0 || rest < 0 || can < 0 || rest < rel || can < rel)
                violations.add("RunScreen.java: invariant 229 - Pause no longer resumes before it "
                    + "asks anything else, or no longer says why a rest has nothing to pause");
        }
    }

    /** Coming steps' apply methods that change a later step, and the first move of each. */
    static final String[] COMING_LATER = { "comingSets", "comingHold", "comingRest", "comingDrop",
        "comingDropTime", "comingRampSteps", "comingRampStepTime", "comingUndo" };
    static final String[] COMING_MOVES = { "setPresetDuration(", "ComingSteps.applyDrop(",
        "ComingSteps.applyDropTime(", "ComingSteps.respreadRamp(", "ComingSteps.setRampStepTime(",
        "ComingSteps.setRampCycles(", "ComingSteps.restoreBlock(", ".uh=", "comingRewrite(",
        "comingRetimeRunning(" };

    /**
     * INVARIANT 230: COMING STEPS CHANGES ONLY A LATER STEP, AND ITS DROP STAYS UNDER THE FLOOR.
     *   (a) every apply asks comingLaterOnly( before its first move - the step playing is
     *       read-only there (the − / + strip is its one place) - and none re-times the step
     *       playing (comingRetimeRunning);
     *   (b) comingDrop asks ComingSteps.dropRefusal( before ComingSteps.applyDrop(, and the
     *       drop is written only there;
     *   (c) in ComingSteps every drop written (`.lo =`) goes through RunEdit.clampLower( (never
     *       at or above the pull), applyDrop holds a raise 1.0 inHg under the pull
     *       (RunEdit.dropUnder - past the floor is the person's call since 2026-09-30, never
     *       past that gap), and a ramp re-spread never puts a step above the higher of its two
     *       ends, nor past the ceiling.
     */
    static void checkComingLaterOnly(String act, String cs, List<String> violations) {
        for (int i = 0; i < COMING_LATER.length; i++) {
            String b = body228(act, "String\\s+" + COMING_LATER[i] + "\\s*\\(", "SessionActivity.java",
                COMING_LATER[i], violations);
            if (b == null) continue;
            int later = b.indexOf("comingLaterOnly(");
            int move = firstOf(b, COMING_MOVES);
            if (later < 0 || (move >= 0 && move < later))
                violations.add("SessionActivity.java: invariant 230 - " + COMING_LATER[i]
                    + " changes the run before it asks comingLaterOnly( - the step playing is "
                    + "read-only in Coming steps");
            if (b.indexOf("comingRetimeRunning(") >= 0)
                violations.add("SessionActivity.java: invariant 230 - " + COMING_LATER[i]
                    + " re-times the step playing - Coming steps changes only later steps");
        }
        String d = body228(act, "String\\s+comingDrop\\s*\\(", "SessionActivity.java", "comingDrop",
            violations);
        if (d != null) {
            int ask = d.indexOf("ComingSteps.dropRefusal("), put = d.indexOf("ComingSteps.applyDrop(");
            if (ask < 0 || put < 0 || put < ask)
                violations.add("SessionActivity.java: invariant 230 - comingDrop does not ask "
                    + "ComingSteps.dropRefusal( before ComingSteps.applyDrop(");
        }
        Matcher lo = Pattern.compile("\\.\\s*lo\\s*=(?!=)([^;]*);").matcher(cs);
        while (lo.find())
            if (lo.group(1).indexOf("RunEdit.clampLower(") < 0)
                violations.add("ComingSteps.java: invariant 230 - a drop is written at line "
                    + lineOf(cs, lo.start()) + " without RunEdit.clampLower( - it could reach the pull");
        Matcher bh = Pattern.compile("\\bbuiltHoldOnly\\s*=(?!=)").matcher(cs);
        if (bh.find())
            violations.add("ComingSteps.java: invariant 230 - line " + lineOf(cs, bh.start())
                + " stamps what a preset was built as by hand; a re-design goes through "
                + "RunEdit.redesigned( (invariant 137)");
        String adt = body228(cs, "void\\s+applyDropTime\\s*\\(", "ComingSteps.java", "applyDropTime",
            violations);
        if (adt != null && (adt.indexOf("if(was<=0&&p.lh>0){") < 0
                || adt.indexOf("RunEdit.redesigned(p,false)") < 0))
            violations.add("ComingSteps.java: invariant 230 - applyDropTime no longer brings only a NEW "
                + "drop under the floor and re-designs the block with it (a hold-only block given a "
                + "drop would keep its drop controls locked while the pump drops)");
        String ad = body228(cs, "void\\s+applyDrop\\s*\\(", "ComingSteps.java", "applyDrop", violations);
        if (ad != null && (ad.indexOf("lo=RunEdit.dropUnder(lo,p.up);") < 0 || ad.indexOf("if(lo>p.lo)") < 0))
            violations.add("ComingSteps.java: invariant 230 - applyDrop no longer holds a raised drop "
                + "1.0 inHg under the pull (RunEdit.dropUnder)");
        String rs = body228(cs, "int\\s+respreadRamp\\s*\\(", "ComingSteps.java", "respreadRamp",
            violations);
        if (rs != null && (rs.indexOf("p.up=Math.min(up,Math.max(a.up,z.up));") < 0
                || rs.indexOf("RunEdit.clampUpper(") < 0))
            violations.add("ComingSteps.java: invariant 230 - respreadRamp can put a step above the "
                + "higher of the ramp's ends or past the ceiling");
    }

    /**
     * INVARIANT 231: WHERE THE STRIP SITS IS A STORED CHOICE AND NOTHING MORE. Model stores
     * runStripWhere and loads it only through clampRunStripWhere( (an unknown value is
     * pinned); showRun places the strip by it - under the chart, or in the pinned footer.
     *   (b) THE STRIP IS NEVER HIDDEN OR SQUEEZED OFF (owner report: a Samsung phone showed the
     *       buttons and no − / + card). paintStrip shows stripBox whatever is playing
     *       (setVisible(stripBox, true) and no other visibility for it anywhere), and a pinned
     *       strip is watched by StripFit, which measures the footer against the screen
     *       (QuickAdjust.fitsPinned) and moves the strip out of the footer, under the chart.
     *   (c) A RAMP'S STEP AND THE WARM-UP SHOW THE FOUR FIGURES (owner request, 0.10): stripNow
     *       fills the grid (fillGrid) for the warm-up, the ramp and the set - three places.
     */
    static void checkStripWhere(String screen, String model, List<String> violations) {
        String fs = flat224(screen);
        int vis = 0, at = -1;
        while ((at = fs.indexOf("setVisible(stripBox,", at + 1)) >= 0) {
            vis++;
            if (!fs.startsWith("setVisible(stripBox,true)", at))
                violations.add("RunScreen.java: invariant 231(b) - stripBox is shown or hidden by "
                    + "something other than true - the strip is never hidden");
        }
        if (vis == 0 || fs.indexOf("stripBox.setVisibility(") >= 0)
            violations.add("RunScreen.java: invariant 231(b) - paintStrip no longer shows the strip "
                + "whatever is playing (setVisible(stripBox, true)), or it is hidden directly");
        String fit = body228(screen, "class\\s+StripFit\\b", "RunScreen.java", "StripFit", violations);
        if (fit != null && (fit.indexOf("QuickAdjust.fitsPinned(") < 0
                || fit.indexOf("footer.removeView(strip)") < 0
                || fit.indexOf("content.addView(strip,") < 0))
            violations.add("RunScreen.java: invariant 231(b) - StripFit no longer measures the pinned "
                + "footer against the screen and moves the strip under the chart when it does not fit");
        String now = body228(screen, "StripNow\\s+stripNow\\s*\\(", "RunScreen.java", "stripNow",
            violations);
        int grids = 0; at = -1;
        while (now != null && (at = now.indexOf("if(QuickAdjust.showsGrid(mode))fillGrid(s,cur);", at + 1)) >= 0)
            grids++;
        if (now != null && grids < 3)
            violations.add("RunScreen.java: invariant 231(c) - stripNow no longer fills the four "
                + "figures for the warm-up, a ramp's step and a set as QuickAdjust.showsGrid says "
                + "(the rule StripGridShapesTest holds every RxBuild shape to; " + grids + " of 3)");
        String m = flat224(model);
        if (m.indexOf("m.runStripWhere=clampRunStripWhere(") < 0
                || m.indexOf("o.put(\"runStripWhere\",runStripWhere);") < 0)
            violations.add("Model.java: invariant 231 - runStripWhere is not saved, or not loaded "
                + "through clampRunStripWhere(");
        String show = body228(screen, "void\\s+showRun\\s*\\(", "RunScreen.java", "showRun", violations);
        if (show != null && (show.indexOf("a.model.runStripWhere==Model.RUN_STRIP_UNDER_CHART") < 0
                || show.indexOf("a.runFooter.addView(strip,") < 0
                || show.indexOf("runContent.addView(strip,") < 0
                || show.indexOf("newStripFit(") < 0))
            violations.add("RunScreen.java: invariant 231 - showRun no longer places the strip by "
                + "the setting (under the chart, or pinned above the buttons)");
        // (g) CHART FIRST ON RAMPS (0.10): the page changes order when the step playing changes
        //     kind, by MOVING the views showRun built. The tick asks (followRampLayout()), and
        //     that method never builds, clears or re-creates a view - a rebuild on the tick is
        //     what once swallowed taps on this screen.
        String tick = body228(screen, "void\\s+refreshRunScreen\\s*\\(", "RunScreen.java",
            "refreshRunScreen", violations);
        if (tick != null && flat224(tick).indexOf("followRampLayout();") < 0)
            violations.add("RunScreen.java: invariant 231(g) - the tick no longer asks whether the "
                + "step's kind changed (followRampLayout()), so \"Chart first on ramps\" never follows "
                + "the step");
        String follow = body228(screen, "void\\s+followRampLayout\\s*\\(", "RunScreen.java",
            "followRampLayout", violations);
        if (follow != null) {
            String ff = flat224(follow);
            if (ff.indexOf("QuickAdjust.chartFirst(") < 0 || ff.indexOf("QuickAdjust.stripInPage(") < 0)
                violations.add("RunScreen.java: invariant 231(g) - followRampLayout no longer takes "
                    + "the order from QuickAdjust.chartFirst / stripInPage (the pure, tested rule)");
            if (ff.indexOf("buildStrip(") >= 0 || ff.indexOf("removeAllViews(") >= 0
                    || ff.indexOf("newButton(") >= 0 || ff.indexOf("newTextView(") >= 0)
                violations.add("RunScreen.java: invariant 231(g) - followRampLayout builds or clears "
                    + "views; it may only MOVE the ones showRun built (a rebuild swallows taps)");
        }
        if (show != null && flat224(show).indexOf("followRampLayout();") < 0)
            violations.add("RunScreen.java: invariant 231(g) - showRun no longer puts the page in "
                + "the ramp order when a ramp's step is what is playing");
    }

    /**
     * INVARIANT 232: THE FIRST-RUN SETUP HIDES THE APP'S HEADER, AND EVERY WAY OFF IT GIVES IT
     * BACK. The setup pins its own SETUP n/6 bar and Back/Next, so the "OpenPump" bar and the
     * pump chip are hidden while it shows (pinSetupChrome -> showTopBar(false)). The header
     * comes back in the ONE place that takes the setup's chrome away (dropSetupChrome ->
     * showTopBar(true)), which enterDest, enterFlow and showConnect already call - so no exit
     * can leave the header hidden. showTopBar covers the bar and its closing rule.
     *   (b) THE TRAINER'S SETUP HIDES IT TOO (owner, 2026-09-30): pinStepChrome, which its steps
     *       and Confirm pin through, hides the header after it drops the chrome before it; and
     *       its save sheet hides it only through hideTopBarWhile, which gives it back when the
     *       sheet is dismissed (setOnDismissListener).
     */
    static void checkSetupHeader(String act, List<String> violations) {
        String pin = body228(act, "void\\s+pinSetupChrome\\s*\\(", "SessionActivity.java",
            "pinSetupChrome", violations);
        if (pin != null && pin.indexOf("showTopBar(false);") < 0)
            violations.add("SessionActivity.java: invariant 232 - pinSetupChrome no longer hides "
                + "the app's header while the first-run setup shows");
        String drop = body228(act, "void\\s+dropSetupChrome\\s*\\(", "SessionActivity.java",
            "dropSetupChrome", violations);
        if (drop != null && drop.indexOf("showTopBar(true);") < 0)
            violations.add("SessionActivity.java: invariant 232 - dropSetupChrome no longer gives "
                + "the app's header back, so an exit from the setup could leave it hidden");
        String bar = body228(act, "void\\s+showTopBar\\s*\\(", "SessionActivity.java",
            "showTopBar", violations);
        if (bar != null && (bar.indexOf("topBarRow.setVisibility(") < 0
                || bar.indexOf("topBarEdge.setVisibility(") < 0))
            violations.add("SessionActivity.java: invariant 232 - showTopBar no longer covers both "
                + "the header and the rule under it");
        int calls = 0, at = -1;
        String fa = flat224(act);
        while ((at = fa.indexOf("dropSetupChrome();", at + 1)) >= 0) calls++;
        if (calls < 4)
            violations.add("SessionActivity.java: invariant 232 - dropSetupChrome is called from "
                + calls + " places, not pinSetupChrome, enterDest, enterFlow and showConnect");
        String step = body228(act, "void\\s+pinStepChrome\\s*\\(", "SessionActivity.java",
            "pinStepChrome", violations);
        if (step != null) {
            int d = step.indexOf("dropSetupChrome();"), h = step.indexOf("showTopBar(false);");
            if (d < 0 || h < d)
                violations.add("SessionActivity.java: invariant 232 - pinStepChrome no longer hides "
                    + "the app's header while the trainer's setup shows (after dropping the chrome "
                    + "before it)");
        }
        String sheet = body228(act, "void\\s+hideTopBarWhile\\s*\\(", "SessionActivity.java",
            "hideTopBarWhile", violations);
        if (sheet != null && (sheet.indexOf("showTopBar(false);") < 0
                || sheet.indexOf("setOnDismissListener(") < 0))
            violations.add("SessionActivity.java: invariant 232 - hideTopBarWhile hides the header "
                + "without giving it back when the trainer setup's save sheet is dismissed");
    }

    static void setupHeaderSelfTests(int[] counts) {
        String act =
              "void pinSetupChrome(View t, View b) { pinStepChrome(t, b); showTopBar(false); }\n"
            + "private void dropSetupChrome() { root.removeView(setupTop); showTopBar(true); }\n"
            + "private void showTopBar(boolean s) { topBarRow.setVisibility(v); topBarEdge.setVisibility(v); }\n"
            + "void enterDest(int s) { dropSetupChrome(); }\n"
            + "void enterFlow(int s) { dropSetupChrome(); }\n"
            + "void showConnect() { dropSetupChrome(); }\n"
            + "void pinStepChrome(View t, View b) { dropSetupChrome(); showTopBar(false); root.addView(t); }\n"
            + "void hideTopBarWhile(AlertDialog d) { showTopBar(false); d.setOnDismissListener(new TopBarBack()); }\n";
        List<String> v = new ArrayList<String>();
        checkSetupHeader(act, v);
        selfCheck(counts, v.isEmpty(), "INV232: the app's shape passes (got " + v + ")");
        String[][] bad = {
            { " showTopBar(false); }", " }", "a setup that keeps the header" },
            { " showTopBar(true); }", " }", "an exit that never gives the header back" },
            { " topBarEdge.setVisibility(v);", "", "a header hidden without its rule" },
            { "void showConnect() { dropSetupChrome(); }", "void showConnect() { }",
              "an exit that does not take the setup's chrome away" },
            { "{ dropSetupChrome(); showTopBar(false); root.addView(t); }",
              "{ dropSetupChrome(); root.addView(t); }", "a trainer setup that keeps the header" },
            { " d.setOnDismissListener(new TopBarBack());", "",
              "a save sheet that never gives the header back" },
        };
        for (int i = 0; i < bad.length; i++) {
            String a2 = act.replace(bad[i][0], bad[i][1]);
            selfCheck(counts, !a2.equals(act), "INV232 self-test edit did not apply: " + bad[i][2]);
            List<String> bv = new ArrayList<String>();
            checkSetupHeader(a2, bv);
            selfCheck(counts, !bv.isEmpty(), "INV232 must reject " + bad[i][2]);
        }
    }

