    /* ===================================================================================== *
     *  INVARIANT 246 - EVERY RAMP STEP IS WHOLE CYCLES OF ITS OWN HOLD AND DROP (0.10, the    *
     *  owner's decision after a manual ramp of 4:21 steps of a 42 s cycle: each step ended 9 s *
     *  into a hold and the pump went straight on to the next pull with no drop; nine 1:40      *
     *  steps of a 4:10 hold never reached a drop at all). ModelWholeCycleRampTest proves the   *
     *  rule over every Set the model can build; this pins the roads to it.                    *
     * ===================================================================================== */

    /**
     * INVARIANT 246: A RAMP STEP IS NEVER CUT INSIDE A HOLD, AND NEVER SHORTER THAN ONE CYCLE.
     *   (a) Model: the ladder times each ramp step as k whole cycles of that step's own cycle
     *       (Set#stepCycleSec); Set#clamp puts a ramp's duration on those whole cycles
     *       (rampDurSec) and clampAll snaps every stored ramp (snapRamp) - load, import;
     *   (b) both editors step a ramp's duration one whole cycle a step (rampDurStepped), never a
     *       flat 30 s, and the set editor re-snaps a ramp (snapEditorDur: snapRamp);
     *   (c) the run's own edits keep whole cycles: the strip's Time per step moves one cycle
     *       (QuickAdjust.stepTimeNext) and asks the step's share of the hour
     *       (QuickAdjust.stepTimeRefusal) before it re-times; Coming steps' time per step and
     *       step count write QuickAdjust's whole cycles (ComingSteps.setRampCycles), so does
     *       its undo; "+ step" is whole cycles (RunEdit.addedStepMs: ComingSteps.cycleSecOf);
     *   (d) no step-time bound is the wire's 255 s: QuickAdjust.MAX[STEP_TIME] and
     *       ComingSteps.STEP_TIME_MAX_SEC come from Model.Set.rampStepMaxSec, and nothing says
     *       "the longest step the pump takes";
     *   (e) the strip on a ramp's step says the ramp's range (QuickAdjust.rampHeadAt).
     */
    static void checkRampWholeCycles(String model, String act, String screen, String quick,
                                     String cs, String re, List<String> violations) {
        String lad = body228(model, "List<Preset>\\s+ladder\\s*\\(", "Model.java", "Set#ladder",
            violations);
        if (lad != null && lad.indexOf("p.durMs=Math.max(1000L,(long)k*stepCycleSec(i,n)*1000L);") < 0)
            violations.add("Model.java: invariant 246 - Set#ladder no longer times a ramp step as "
                + "whole cycles of its own hold + drop (k * stepCycleSec)");
        String mf = flat224(model);
        if (mf.indexOf("if(!fromPlan)dur=rampDurSec();") < 0)
            violations.add("Model.java: invariant 246 - Set#clamp no longer puts a ramp's duration "
                + "on whole cycles (rampDurSec)");
        String ca = body228(model, "void\\s+clampAll\\s*\\(", "Model.java", "clampAll", violations);
        if (ca != null && ca.indexOf("sets.get(i).snapRamp();") < 0)
            violations.add("Model.java: invariant 246 - clampAll no longer snaps every stored ramp "
                + "to whole cycles (snapRamp) - an old or imported ramp would end a step in a hold");
        String[][] eds = { { "void\\s+bump\\s*\\(\\s*int\\s+field", "bump" },
                           { "void\\s+bumpManual\\s*\\(", "bumpManual" } };
        for (int i = 0; i < eds.length; i++) {
            String b = body228(act, eds[i][0], "SessionActivity.java", eds[i][1], violations);
            if (b == null) continue;
            if (b.indexOf("s.dur=s.ramp?s.rampDurStepped(d)") < 0 || b.indexOf("s.dur+d*30") >= 0)
                violations.add("SessionActivity.java: invariant 246 - " + eds[i][1] + " no longer "
                    + "steps a ramp's duration one whole cycle a step (rampDurStepped)");
        }
        String sn = body228(act, "void\\s+snapEditorDur\\s*\\(", "SessionActivity.java",
            "snapEditorDur", violations);
        if (sn != null && sn.indexOf("s.snapRamp();") < 0)
            violations.add("SessionActivity.java: invariant 246 - snapEditorDur no longer snaps a "
                + "ramp to whole cycles (snapRamp)");
        String qr = body228(act, "String\\s+quickRampStep\\s*\\(", "SessionActivity.java",
            "quickRampStep", violations);
        if (qr != null) {
            int next = qr.indexOf("QuickAdjust.stepTimeNext("), ask = qr.indexOf("QuickAdjust.stepTimeRefusal(");
            int go = qr.indexOf("comingRetimeRunning(");
            if (next < 0 || ask < 0 || go < 0 || go < ask || go < next)
                violations.add("SessionActivity.java: invariant 246 - the strip's Time per step no "
                    + "longer moves one whole cycle (QuickAdjust.stepTimeNext) and asks the step's "
                    + "share of the hour (QuickAdjust.stepTimeRefusal) before it re-times");
        }
        String[][] coming = { { "comingRampStepTime", "ComingSteps.setRampCycles(" },
                              { "comingRampSteps", "ComingSteps.setRampCycles(" },
                              { "comingUndo", "ComingSteps.setRampCycles(" } };
        for (int i = 0; i < coming.length; i++) {
            String b = body228(act, "String\\s+" + coming[i][0] + "\\s*\\(", "SessionActivity.java",
                coming[i][0], violations);
            if (b == null) continue;
            if (b.indexOf(coming[i][1]) < 0 || b.indexOf("ComingSteps.setRampStepTime(") >= 0)
                violations.add("SessionActivity.java: invariant 246 - " + coming[i][0] + " no "
                    + "longer writes a ramp's steps in whole cycles (ComingSteps.setRampCycles)");
        }
        String rs = body228(act, "String\\s+comingRampSteps\\s*\\(", "SessionActivity.java",
            "comingRampSteps", violations);
        if (rs != null && rs.indexOf("ComingSteps.setRampCycles(") < rs.indexOf("ComingSteps.respreadRamp("))
            violations.add("SessionActivity.java: invariant 246 - comingRampSteps re-spreads the "
                + "ramp after it sets its whole cycles - the new steps would keep a cut length");
        String add = body228(re, "long\\s+addedStepMs\\s*\\(", "RunEdit.java", "addedStepMs", violations);
        if (add != null && add.indexOf("ComingSteps.cycleSecOf(") < 0)
            violations.add("RunEdit.java: invariant 246 - \"+ step\" no longer runs whole cycles of "
                + "the added step (addedStepMs: ComingSteps.cycleSecOf)");
        String qf = flat224(quick), cf = flat224(cs);
        if (qf.indexOf("600,Model.Set.rampStepMaxSec(2),600};") < 0)
            violations.add("QuickAdjust.java: invariant 246 - MAX[STEP_TIME] is no longer a ramp "
                + "step's share of the hour (Model.Set.rampStepMaxSec) - a step is the app's clock, "
                + "not the wire's 255 s");
        if (cf.indexOf("STEP_TIME_MAX_SEC=Model.Set.rampStepMaxSec(") < 0)
            violations.add("ComingSteps.java: invariant 246 - STEP_TIME_MAX_SEC is no longer a ramp "
                + "step's share of the hour (Model.Set.rampStepMaxSec)");
        String[] said = { quick, cs, screen, act };
        String[] names = { "QuickAdjust.java", "ComingSteps.java", "RunScreen.java", "SessionActivity.java" };
        for (int i = 0; i < said.length; i++)
            if (said[i].indexOf("longest step the pump takes") >= 0)
                violations.add(names[i] + ": invariant 246 - says \"the longest step the pump takes\" "
                    + "- the pump takes one hold or one drop of 255 s; a step is the app's clock");
        String sr = body228(screen, "String\\s+stripRefusal\\s*\\(\\s*StripNow\\s+s\\s*,\\s*int\\s+field\\s*,"
            + "\\s*int\\s+dir\\s*,\\s*int\\s+pullCap", "RunScreen.java", "stripRefusal", violations);
        if (sr != null && sr.indexOf("QuickAdjust.stepTimeRefusal(") < 0)
            violations.add("RunScreen.java: invariant 246 - the strip no longer asks Time per step "
                + "as it will go, one whole cycle (QuickAdjust.stepTimeRefusal)");
        if (flat224(screen).indexOf("s.head=QuickAdjust.rampHeadAt(") < 0)
            violations.add("RunScreen.java: invariant 246 - the strip on a ramp's step no longer "
                + "says where the ramp goes (QuickAdjust.rampHeadAt)");
    }

    static void checkRampWholeCyclesFiles(String dir, List<String> violations) throws IOException {
        String model = runScreenRaw(dir, "Model.java", violations);
        String act = runScreenRaw(dir, "SessionActivity.java", violations);
        String screen = runScreenRaw(dir, "RunScreen.java", violations);
        String quick = runScreenRaw(dir, "QuickAdjust.java", violations);
        String cs = runScreenRaw(dir, "ComingSteps.java", violations);
        String re = runScreenRaw(dir, "RunEdit.java", violations);
        if (model != null && act != null && screen != null && quick != null && cs != null && re != null)
            checkRampWholeCycles(model, act, screen, quick, cs, re, violations);
    }

    /** Invariant 246's self-test: the app's shapes pass, and each road taken off is caught. */
    static void rampWholeCyclesSelfTests(int[] counts) {
        String model =
              "public List<Preset> ladder() { int k = ramp ? rampCycles() : 0; for (int i = 0; i < n; i++) {"
            + " if (ramp) { p.durMs = Math.max(1000L, (long) k * stepCycleSec(i, n) * 1000L); } } return out; }\n"
            + "public void clamp(int ceilKpa) { if (ramp) { steps = rampSteps(); if (!fromPlan) dur = rampDurSec(); } }\n"
            + "public void clampAll() { for (int i = 0; i < sets.size(); i++) { sets.get(i).clamp(ceilKpa);"
            + " sets.get(i).snapRamp(); } }\n";
        String act =
              "private void bump(int field, int d) { switch (field) { case Tap.DUR:"
            + " s.dur = s.ramp ? s.rampDurStepped(d) : Model.snapDurToCycle(s.dur, s.uh, s.lh) + d * s.cycle(); break; } }\n"
            + "private void bumpManual(int field, int d) { switch (field) { case Tap.DUR:"
            + " s.dur = s.ramp ? s.rampDurStepped(d) : Model.snapDurToCycle(s.dur, s.uh, s.lh) + d * s.cycle(); break; } }\n"
            + "private void snapEditorDur(Model.Set s) { if (s.ramp) { s.snapRamp(); return; } }\n"
            + "String quickRampStep(int d) { int next = QuickAdjust.stepTimeNext(len, dir, cyc);"
            + " String why = QuickAdjust.stepTimeRefusal(len, next, cyc, steps); if (!comingRetimeRunning(d)) return x; return null; }\n"
            + "String comingRampStepTime(int si, int d) { ComingSteps.setRampCycles(plan, first, n, cycles); return null; }\n"
            + "String comingRampSteps(int si, int d) { ComingSteps.respreadRamp(plan, 1, 2, 3, 4, 5);"
            + " ComingSteps.setRampCycles(plan, first, n, cycles); return null; }\n"
            + "String comingUndo(int si) { ComingSteps.setRampCycles(plan, at, was.steps, was.cycles); return null; }\n";
        String screen =
              "private String stripRefusal(StripNow s, int field, int dir, int pullCap) {"
            + " return QuickAdjust.stepTimeRefusal(v, next, s.stepCycle, s.rampSteps); }\n"
            + "private StripNow stripNow(long now) { s.head = QuickAdjust.rampHeadAt(a.plan, a.planIdx, c); return s; }\n";
        String quick = "public static final int[] MAX = { 34, 255, 10, 30, 600, Model.Set.rampStepMaxSec(2), 600 };\n";
        String cs = "public static final int STEP_TIME_MAX_SEC = Model.Set.rampStepMaxSec(RAMP_STEPS_MIN);\n";
        String re = "public static long addedStepMs(List<Model.Preset> plan, int planIdx) {"
            + " return (long) cycles * ComingSteps.cycleSecOf(z) * 1000L; }\n";
        List<String> v = new ArrayList<String>();
        checkRampWholeCycles(model, act, screen, quick, cs, re, v);
        selfCheck(counts, v.isEmpty(), "INV246: the app's shapes pass (got " + v + ")");
        String[][] bad = {
            { "M", "a ramp step timed as an even share of the duration",
              "p.durMs = Math.max(1000L, (long) k * stepCycleSec(i, n) * 1000L);",
              "p.durMs = Math.max(1000L, (long) dur * 1000L / n);" },
            { "M", "a ramp's duration left off its whole cycles", "if (!fromPlan) dur = rampDurSec();", "" },
            { "M", "a stored ramp loaded unsnapped", " sets.get(i).snapRamp();", "" },
            { "A", "the set editor's flat 30 s ramp stepper",
              "private void bump(int field, int d) { switch (field) { case Tap.DUR: s.dur = s.ramp ? s.rampDurStepped(d)",
              "private void bump(int field, int d) { switch (field) { case Tap.DUR: s.dur = s.ramp ? s.dur + d * 30" },
            { "A", "the manual editor's flat 30 s ramp stepper",
              "private void bumpManual(int field, int d) { switch (field) { case Tap.DUR: s.dur = s.ramp ? s.rampDurStepped(d)",
              "private void bumpManual(int field, int d) { switch (field) { case Tap.DUR: s.dur = s.ramp ? s.dur + d * 30" },
            { "A", "a ramp the set editor never snaps", "if (s.ramp) { s.snapRamp(); return; }", "if (s.ramp) return;" },
            { "A", "Time per step by 5 s", "int next = QuickAdjust.stepTimeNext(len, dir, cyc);", "int next = len + d;" },
            { "A", "Time per step re-timed before the hour is asked",
              " String why = QuickAdjust.stepTimeRefusal(len, next, cyc, steps); if (!comingRetimeRunning(d)) return x;",
              " if (!comingRetimeRunning(d)) return x; String why = QuickAdjust.stepTimeRefusal(len, next, cyc, steps);" },
            { "A", "Coming steps' time per step as an even length",
              "String comingRampStepTime(int si, int d) { ComingSteps.setRampCycles(plan, first, n, cycles);",
              "String comingRampStepTime(int si, int d) { ComingSteps.setRampStepTime(plan, first, n, sec);" },
            { "A", "a re-spread left at its cut length",
              " ComingSteps.setRampCycles(plan, first, n, cycles); return null; }\nString comingUndo",
              " return null; }\nString comingUndo" },
            { "A", "an undo that puts back a cut length",
              "ComingSteps.setRampCycles(plan, at, was.steps, was.cycles);",
              "ComingSteps.setRampStepTime(plan, at, was.steps, was.stepSec);" },
            { "R", "\"+ step\" as the others' average length", "ComingSteps.cycleSecOf(z)", "1" },
            { "Q", "the wire's 255 s as the longest step", "Model.Set.rampStepMaxSec(2)", "255" },
            { "C", "Coming steps' longest step as the wire's", "Model.Set.rampStepMaxSec(RAMP_STEPS_MIN)",
              "Proto.WIRE_HOLD_MAX" },
            { "S", "the strip asking Time per step as 5 s", "QuickAdjust.stepTimeRefusal(v, next, s.stepCycle, s.rampSteps)",
              "QuickAdjust.stepRefusal(field, v, dir, -1, e, c)" },
            { "S", "the ramp's range unsaid", "QuickAdjust.rampHeadAt(a.plan, a.planIdx, c)", "QuickAdjust.headOf(mode)" },
            { "Q", "the false \"pump takes\" words", "public static final int[] MAX",
              "static final String W = \"4:15 is the longest step the pump takes.\"; public static final int[] MAX" },
        };
        for (int i = 0; i < bad.length; i++) {
            String k = bad[i][0];
            String m2 = "M".equals(k) ? model.replace(bad[i][2], bad[i][3]) : model;
            String a2 = "A".equals(k) ? act.replace(bad[i][2], bad[i][3]) : act;
            String s2 = "S".equals(k) ? screen.replace(bad[i][2], bad[i][3]) : screen;
            String q2 = "Q".equals(k) ? quick.replace(bad[i][2], bad[i][3]) : quick;
            String c2 = "C".equals(k) ? cs.replace(bad[i][2], bad[i][3]) : cs;
            String r2 = "R".equals(k) ? re.replace(bad[i][2], bad[i][3]) : re;
            selfCheck(counts, !(m2.equals(model) && a2.equals(act) && s2.equals(screen)
                && q2.equals(quick) && c2.equals(cs) && r2.equals(re)),
                "INV246 self-test edit did not apply: " + bad[i][1]);
            List<String> bv = new ArrayList<String>();
            checkRampWholeCycles(m2, a2, s2, q2, c2, r2, bv);
            selfCheck(counts, !bv.isEmpty(), "INV246 must reject " + bad[i][1]);
        }
    }

    /* ===================================================================================== *
     *  INVARIANT 247 - A LIVE HOLD / DROP-TIME CHANGE KEEPS A RAMP'S STEPS ON WHOLE CYCLES     *
     *  (0.10 safety follow-up). A live change on a ramp's step of several cycles used to keep  *
     *  the step's length: with a new cycle the step ended inside a hold and the pump went     *
     *  straight on to the next step's pull with no drop. RampLiveEditWholeTest sweeps the     *
     *  arithmetic over edit sequences; this pins the engine's roads to it.                     *
     * ===================================================================================== */

    /**
     * INVARIANT 247:
     *   (a) a change carried on (carryOnPlanFor) on a ramp's step of several cycles moves the
     *       step's end to a cycle end (co.endMoveMs = rampWholeMoveMs(...)) - never kept;
     *   (b) a restart (keepSetsWhole: a re-arm, a Revert, a convergence) does the same for a
     *       ramp's step - never "a ramp keeps its end" (return 0L on src.ramp);
     *   (c) the hold written for a restart is capped against that new end (fireAtAfterCycle);
     *   (d) the later steps are put on whole cycles after "Rest of this ramp" (commitEdit:
     *       wholeCyclesAfter after the shift), the sheet's Reshape (applyRampReshape) and its
     *       recount (resizeRemainingRamp: RunEdit.wholeCyclesLater);
     *   (e) Time per step moves the step playing by exactly one cycle (d from next - len);
     *   (f) the extend button on a ramp's step says what it adds (RunEdit.rampExtendLabel);
     *   (g) "+ step" asks each step's share of the hour (RunEdit.addStepShareRefusal).
     */
    static void checkRampLiveWhole(String act, String screen, String re, List<String> violations) {
        String co = body228(act, "HoldCarryOn\\.Plan\\s+carryOnPlanFor\\s*\\(",
            "SessionActivity.java", "carryOnPlanFor", violations);
        if (co != null && (co.indexOf("co.endMoveMs=rampWholeMoveMs(co.cycleEndsInMs,") < 0
                || co.indexOf("co.rampWhole=true;") < 0))
            violations.add("SessionActivity.java: invariant 247 - a change carried on a ramp's step "
                + "no longer ends the step as a cycle ends (carryOnPlanFor: rampWholeMoveMs)");
        String ks = body228(act, "long\\s+keepSetsWhole\\s*\\(", "SessionActivity.java",
            "keepSetsWhole", violations);
        if (ks != null && (ks.indexOf("rampWhole?rampWholeMoveMs(cycle,cycle,now)") < 0
                || ks.indexOf("src.ramp)return0L;") >= 0))
            violations.add("SessionActivity.java: invariant 247 - a restart on a ramp's step keeps "
                + "its end again (keepSetsWhole: rampWholeMoveMs) - it would end inside a hold");
        String fa = body228(act, "long\\s+fireAtAfterCycle\\s*\\(", "SessionActivity.java",
            "fireAtAfterCycle", violations);
        if (fa != null && fa.indexOf("presetFireAt+rampWholeMoveMs(cyc,cyc,now)") < 0)
            violations.add("SessionActivity.java: invariant 247 - the hold written on a ramp's step "
                + "is capped short of its whole-cycle end (fireAtAfterCycle)");
        String ce = body228(act, "void\\s+commitEdit\\s*\\(", "SessionActivity.java",
            "commitEdit", violations);
        if (ce != null) {
            int sh = ce.indexOf("shiftRemainingOfSet("), wc = ce.indexOf("wholeCyclesAfter(occLeft)");
            if (sh < 0 || wc < 0 || wc < sh)
                violations.add("SessionActivity.java: invariant 247 - \"Rest of this ramp\" no "
                    + "longer puts the later steps on whole cycles after moving them (commitEdit: "
                    + "wholeCyclesAfter)");
        }
        String rr = body228(act, "String\\s+resizeRemainingRamp\\s*\\(", "SessionActivity.java",
            "resizeRemainingRamp", violations);
        if (rr != null && rr.indexOf("RunEdit.wholeCyclesLater(") < 0)
            violations.add("SessionActivity.java: invariant 247 - the sheet's recount leaves its steps "
                + "off whole cycles (resizeRemainingRamp: RunEdit.wholeCyclesLater)");
        String qr = body228(act, "String\\s+quickRampStep\\s*\\(", "SessionActivity.java",
            "quickRampStep", violations);
        if (qr != null && (qr.indexOf("longd=(long)(next-len)*1000L;") < 0
                || qr.indexOf("next*1000L-cur.durMs") >= 0))
            violations.add("SessionActivity.java: invariant 247 - Time per step no longer moves the "
                + "step playing by exactly one cycle (quickRampStep: next - len)");
        String ar = body228(screen, "void\\s+applyRampReshape\\s*\\(", "RunScreen.java",
            "applyRampReshape", violations);
        if (ar != null) {
            int rs = ar.indexOf("RunEdit.reshapeRemaining("), wc = ar.indexOf("a.wholeCyclesAfter(n);");
            if (rs < 0 || wc < 0 || wc < rs)
                violations.add("RunScreen.java: invariant 247 - the sheet's Reshape leaves its steps "
                    + "off whole cycles (applyRampReshape: a.wholeCyclesAfter)");
        }
        String tc = body228(screen, "void\\s+refreshTimerControls\\s*\\(", "RunScreen.java",
            "refreshTimerControls", violations);
        if (tc != null && tc.indexOf("cycleStep?RunEdit.rampExtendLabel(sn.stepCycle)") < 0)
            violations.add("RunScreen.java: invariant 247 - the extend button on a ramp's step no "
                + "longer says the cycle it adds (RunEdit.rampExtendLabel)");
        String as = body228(re, "String\\s+addStepRefusal\\s*\\(", "RunEdit.java",
            "addStepRefusal", violations);
        if (as != null && as.indexOf("addStepShareRefusal(") < 0)
            violations.add("RunEdit.java: invariant 247 - \"+ step\" no longer asks each step's "
                + "share of the hour (addStepShareRefusal)");
    }

    static void checkRampLiveWholeFiles(String dir, List<String> violations) throws IOException {
        String act = runScreenRaw(dir, "SessionActivity.java", violations);
        String screen = runScreenRaw(dir, "RunScreen.java", violations);
        String re = runScreenRaw(dir, "RunEdit.java", violations);
        if (act != null && screen != null && re != null)
            checkRampLiveWhole(act, screen, re, violations);
    }

    /** Invariant 247's self-test: the app's shapes pass, and each road taken off is caught. */
    static void rampLiveWholeSelfTests(int[] counts) {
        String act =
              "HoldCarryOn.Plan carryOnPlanFor(int uh, int lh) { HoldCarryOn.Plan co = x;"
            + " if (ramp) { co.rampWhole = true; co.endMoveMs = rampWholeMoveMs(co.cycleEndsInMs, c, now); } return co; }\n"
            + "private long keepSetsWhole(boolean resumed) { long move = rampWhole ? rampWholeMoveMs(cycle, cycle, now)"
            + " : SetClock.retimeMs(left, cycle, presetFireAt - now); return move; }\n"
            + "private long fireAtAfterCycle(int uh, int lh, long now) { if (src != null && src.ramp)"
            + " return presetFireAt + rampWholeMoveMs(cyc, cyc, now); return presetFireAt; }\n"
            + "private void commitEdit(PendingChange.Change c) { shiftRemainingOfSet(occLeft, b);"
            + " if (rampOcc) wholeCyclesAfter(occLeft); }\n"
            + "String resizeRemainingRamp(int n) { RunEdit.wholeCyclesLater(plan, planIdx, m, r); return null; }\n"
            + "String quickRampStep(int d0) { long d = (long) (next - len) * 1000L; return null; }\n";
        String screen =
              "private void applyRampReshape() { int n = RunEdit.reshapeRemaining(a.plan, 1);"
            + " a.wholeCyclesAfter(n); }\n"
            + "private void refreshTimerControls() { setText(b, r ? x"
            + " : cycleStep ? RunEdit.rampExtendLabel(sn.stepCycle) : y); }\n";
        String re = "public static String addStepRefusal(List<Model.Preset> plan, int i) {"
            + " String share = addStepShareRefusal(plan, i, n, added); return share; }\n";
        List<String> v = new ArrayList<String>();
        checkRampLiveWhole(act, screen, re, v);
        selfCheck(counts, v.isEmpty(), "INV247: the app's shapes pass (got " + v + ")");
        String[][] bad = {
            { "A", "a carried-on change keeping the ramp step's end",
              "co.endMoveMs = rampWholeMoveMs(co.cycleEndsInMs, c, now);", "" },
            { "A", "a restart keeping a ramp step's end",
              "long move = rampWhole ? rampWholeMoveMs(cycle, cycle, now) :",
              "if (src.ramp) return 0L; long move =" },
            { "A", "the restart's hold capped at the old end",
              "return presetFireAt + rampWholeMoveMs(cyc, cyc, now);", "return presetFireAt;" },
            { "A", "later steps left off whole cycles", " if (rampOcc) wholeCyclesAfter(occLeft);", "" },
            { "A", "later steps snapped before they moved",
              "shiftRemainingOfSet(occLeft, b); if (rampOcc) wholeCyclesAfter(occLeft);",
              "if (rampOcc) wholeCyclesAfter(occLeft); shiftRemainingOfSet(occLeft, b);" },
            { "A", "the recount left even", "RunEdit.wholeCyclesLater(plan, planIdx, m, r);", "" },
            { "A", "Time per step rounded to a multiple",
              "long d = (long) (next - len) * 1000L;", "long d = next * 1000L - cur.durMs;" },
            { "S", "the reshape left off whole cycles", " a.wholeCyclesAfter(n);", "" },
            { "S", "\"+30 s step\" on a ramp's step of cycles",
              "cycleStep ? RunEdit.rampExtendLabel(sn.stepCycle) : y", "\"+30 s step\"" },
            { "R", "\"+ step\" past a step's share", "String share = addStepShareRefusal(plan, i, n, added);",
              "String share = null;" },
        };
        for (int i = 0; i < bad.length; i++) {
            String k = bad[i][0];
            String a2 = "A".equals(k) ? act.replace(bad[i][2], bad[i][3]) : act;
            String s2 = "S".equals(k) ? screen.replace(bad[i][2], bad[i][3]) : screen;
            String r2 = "R".equals(k) ? re.replace(bad[i][2], bad[i][3]) : re;
            selfCheck(counts, !(a2.equals(act) && s2.equals(screen) && r2.equals(re)),
                "INV247 self-test edit did not apply: " + bad[i][1]);
            List<String> bv = new ArrayList<String>();
            checkRampLiveWhole(a2, s2, r2, bv);
            selfCheck(counts, !bv.isEmpty(), "INV247 must reject " + bad[i][1]);
        }
    }

    /* ===================================================================================== *
     *  INVARIANT 248 - TRADITIONAL GIRTH GROWS BY ITS WEEK AT THE LEVEL (the owner's decision, *
     *  0.10). Its holds are Plan#traditionalSets of its week, so the week must move for it as  *
     *  the interval table's does; TraditionalGrowthTest walks the year through the engine.     *
     * ===================================================================================== */

    /**
     * INVARIANT 248:
     *   (a) the Trainer's week advance (TrainerScreen#advanceWeekIndexes) runs for traditional
     *       girth too - it no longer returns for anything but interval - counting on the
     *       style's own track, and starts an older track's growth once (Mint.startWeekGrowth);
     *   (b) the miss policy judges traditional's weeks too, on its own track;
     *   (c) the rewrite that brings a traditional routine onto the growth says so
     *       (SessionActivity#applyPlanTo: Say.traditionalGrowthDetail);
     *   (d) the prescription reads the growth (Mint.baseSets: Plan.traditionalSets), never the
     *       old flat start;
     *   (e) THE HALF START (0.10): the week advances from the track itself
     *       (Mint.advanceFromAnchor(style, g, weeks)), so a build-up at a level whose own growth
     *       stops sooner still gets its weeks; and an older track is started before the sync
     *       rewrites anything from it (SessionActivity#syncPlanRoutines: Mint.startWeekGrowth
     *       before applyPlanTo) - Today syncs before the Trainer tab is drawn, and an unstarted
     *       track reads the level's whole count.
     */
    static void checkTraditionalWeeks(String trainer, String act, String mint,
                                      List<String> violations) {
        String aw = body228(trainer, "void\\s+advanceWeekIndexes\\s*\\(", "TrainerScreen.java",
            "advanceWeekIndexes", violations);
        if (aw != null) {
            if (aw.indexOf("if(a.model.trainerGirthStyle!=Plan.TRACK_GIRTH_INTERVAL)return;") >= 0
                    || aw.indexOf("Mint.advanceFromAnchor(style,") < 0
                    || aw.indexOf("TrainerTab.accumulatedTrainingWeeks(a.model,style,") < 0)
                violations.add("TrainerScreen.java: invariant 248 - the week advance no longer moves "
                    + "traditional girth's week on its own track - its holds would never grow");
            if (aw.indexOf("Mint.startWeekGrowth(style,g,now)") < 0)
                violations.add("TrainerScreen.java: invariant 248 - an older traditional track no "
                    + "longer starts its growth once from its first week (Mint.startWeekGrowth)");
            if (aw.indexOf("Mint.advanceFromAnchor(style,g,weeks)") < 0)
                violations.add("TrainerScreen.java: invariant 248 - the week no longer advances "
                    + "from the track itself (Mint.advanceFromAnchor(style, g, weeks)) - a "
                    + "traditional build-up at Level 2 or 4 would never add a hold");
        }
        String sp = body228(act, "void\\s+syncPlanRoutines\\s*\\(", "SessionActivity.java",
            "syncPlanRoutines", violations);
        if (sp != null) {
            int started = sp.indexOf("Mint.startWeekGrowth(model.trainerGirthStyle,model.trainerGirth,");
            int rewrite = sp.indexOf("applyPlanTo(");
            if (started < 0 || rewrite < 0 || started > rewrite)
                violations.add("SessionActivity.java: invariant 248 - the sync no longer starts an "
                    + "older traditional track before it rewrites from it - the first rewrite "
                    + "would read the level's whole count, not the half start");
        }
        String mp = body228(trainer, "void\\s+applyMissPolicy\\s*\\(", "TrainerScreen.java",
            "applyMissPolicy", violations);
        if (mp != null && (mp.indexOf("if(a.model.trainerGirthStyle!=Plan.TRACK_GIRTH_INTERVAL)return;") >= 0
                || mp.indexOf("TrainerTab.trainedDaysOnTrack(a.model,style,") < 0))
            violations.add("TrainerScreen.java: invariant 248 - the miss policy no longer judges "
                + "traditional's weeks on its own track");
        String ap = body228(act, "boolean\\s+applyPlanTo\\s*\\(", "SessionActivity.java",
            "applyPlanTo", violations);
        if (ap != null && ap.indexOf("Say.traditionalGrowthDetail(wasSig,e.sig,yieldBefore)") < 0)
            violations.add("SessionActivity.java: invariant 248 - the rewrite onto traditional's "
                + "growth no longer says so (Say.traditionalGrowthDetail)");
        String bs = body228(mint, "int\\s+baseSets\\s*\\(\\s*int\\s+track\\s*,\\s*int\\s+level\\s*,"
            + "\\s*int\\s+weekIndex\\s*,\\s*int\\s+carriedSets", "Mint.java", "baseSets", violations);
        if (bs != null && (bs.indexOf("returnPlan.traditionalSets(level,weekIndex);") < 0
                || bs.indexOf("TRADITIONAL_START.sets") >= 0))
            violations.add("Mint.java: invariant 248 - traditional's sets no longer grow by its week "
                + "(baseSets: Plan.traditionalSets)");
    }

    static void checkTraditionalWeeksFiles(String dir, List<String> violations) throws IOException {
        String trainer = runScreenRaw(dir, "TrainerScreen.java", violations);
        String act = runScreenRaw(dir, "SessionActivity.java", violations);
        String mint = runScreenRaw(dir, "Mint.java", violations);
        if (trainer != null && act != null && mint != null)
            checkTraditionalWeeks(trainer, act, mint, violations);
    }

